/// Safety: src covers size_of::<V>() readable bytes representing valid Copy V.
unsafe fn load<V: Copy, T>(src: *const T) -> V {
    src.cast::<V>().read_unaligned()
}
// Source: src/opts/SkRasterPipeline_opts.h:2002-2005
/// Safety: dst covers size_of::<V>() exclusively writable bytes.
unsafe fn store<V: Copy, T>(dst: *mut T, value: V) {
    dst.cast::<V>().write_unaligned(value);
}

