pub fn from_half(h: u16) -> f32 {
    let sem = h as u32;
    let sign = sem & 0x8000;
    let em = sem ^ sign;
    let denorm = (em as i32) < 0x0400;
    let normal = f32::from_bits(
        (sign << 16)
            .wrapping_add(em << 13)
            .wrapping_add((127 - 15) << 23),
    );
    if denorm {
        0.0
    } else {
        normal
    }
}
