pub fn css_lab_to_xyz(p: &mut Registers) {
    const K: f32 = 24389.0 / 27.0;
    const E: f32 = 216.0 / 24389.0;
    let mut f = [0.0; 3];
    f[1] = (p.r + 16.0) * (1.0 / 116.0);
    f[0] = (p.g * (1.0 / 500.0)) + f[1];
    f[2] = f[1] - (p.b * (1.0 / 200.0));
    let cubed = [f[0] * f[0] * f[0], f[1] * f[1] * f[1], f[2] * f[2] * f[2]];
    let xyz = [
        if cubed[0] > E {
            cubed[0]
        } else {
            (116.0 * f[0] - 16.0) * (1.0 / K)
        },
        if p.r > K * E {
            cubed[1]
        } else {
            p.r * (1.0 / K)
        },
        if cubed[2] > E {
            cubed[2]
        } else {
            (116.0 * f[2] - 16.0) * (1.0 / K)
        },
    ];
    const D50: [f32; 3] = [0.3457 / 0.3585, 1.0, (1.0 - 0.3457 - 0.3585) / 0.3585];
    p.r = xyz[0] * D50[0];
    p.g = xyz[1] * D50[1];
    p.b = xyz[2] * D50[2];
}
