/// Safety: idx must address initialized entries in all four factor/bias arrays.
unsafe fn gradient_lookup(
    p: &mut Registers,
    c: &crate::src::core::SkRasterPipelineOpContexts::GradientCtx,
    idx: u32,
    t: f32,
) {
    let fr = c.factors[0].add(idx as usize).read();
    let br = c.biases[0].add(idx as usize).read();
    let fg = c.factors[1].add(idx as usize).read();
    let bg = c.biases[1].add(idx as usize).read();
    let fb = c.factors[2].add(idx as usize).read();
    let bb = c.biases[2].add(idx as usize).read();
    let fa = c.factors[3].add(idx as usize).read();
    let ba = c.biases[3].add(idx as usize).read();
    p.r = mad(t, fr, br);
    p.g = mad(t, fg, bg);
    p.b = mad(t, fb, bb);
    p.a = mad(t, fa, ba);
}
