            biases
                .as_mut_ptr()
                .cast::<F>()
                .add(1)
                .write(core::mem::transmute(lasx_helpers::gather(c.biases[1], idx)));
            factors
                .as_mut_ptr()
                .cast::<F>()
                .add(2)
                .write(core::mem::transmute(lasx_helpers::gather(
                    c.factors[2],
                    idx,
                )));
            biases
                .as_mut_ptr()
                .cast::<F>()
                .add(2)
                .write(core::mem::transmute(lasx_helpers::gather(c.biases[2], idx)));
