/// Safety: stopCount is nonzero and scaled t is a finite valid native unsigned
/// conversion; the resulting index must address all gradient arrays.
pub unsafe fn evenly_spaced_gradient(
    p: &mut Registers,
    c: &crate::src::core::SkRasterPipelineOpContexts::GradientCtx,
) {
    let t = p.r;
    let idx = (t * (c.stopCount - 1) as f32) as u32;
    gradient_lookup(p, c, idx, t);
}
// Source: src/opts/SkRasterPipeline_opts.h:3807-3817
/// Safety: ts contains stopCount entries and factors/biases cover every index
/// selected by the original threshold loop.
pub unsafe fn gradient(
    p: &mut Registers,
    c: &crate::src::core::SkRasterPipelineOpContexts::GradientCtx,
) {
    let t = p.r;
    let mut idx = 0u32;
    for i in 1..c.stopCount {
        idx = idx.wrapping_add(if t >= c.ts.add(i).read() { 1 } else { 0 });
    }
    gradient_lookup(p, c, idx, t);
}
