// Source: src/opts/SkRasterPipeline_opts.h:3828-3852
pub fn xy_to_unit_angle(p: &mut Registers) {
    let x = p.r;
    let y = p.g;
    let xabs = abs_(x);
    let yabs = abs_(y);
    let slope = min_f32(xabs, yabs) / max_f32(xabs, yabs);
    let s = slope * slope;
    let mut phi = slope
        * (0.15912117063999176025390625_f32
            + s * (-5.185396969318389892578125e-2_f32
                + s * (2.476101927459239959716796875e-2_f32
                    + s * (-7.0547382347285747528076171875e-3_f32))));
    phi = if xabs < yabs { 0.25 - phi } else { phi };
    phi = if x < 0.0 { 0.5 - phi } else { phi };
    phi = if y < 0.0 { 1.0 - phi } else { phi };
    phi = if phi != phi { 0.0 } else { phi };
    p.r = phi;
}
