/// Safety: ctx addresses at least one readable scalar mask (possibly unaligned).
pub unsafe fn apply_vector_mask(p: &mut Registers, ctx: *const u32) {
    let mask = ctx.read_unaligned();
    p.r = f32::from_bits(p.r.to_bits() & mask);
    p.g = f32::from_bits(p.g.to_bits() & mask);
    p.b = f32::from_bits(p.b.to_bits() & mask);
    p.a = f32::from_bits(p.a.to_bits() & mask);
}
