fn compute_perlin_vector(sample: u32, x: f32, y: f32) -> f32 {
    let (sampleLo, sampleHi) = if cfg!(target_endian = "big") {
        (sample >> 16, sample & 0xffff)
    } else {
        (sample & 0xffff, sample >> 16)
    };
    let vecX = mad(sampleLo as f32, 2.0 / 65535.0, -1.0);
    let vecY = mad(sampleHi as f32, 2.0 / 65535.0, -1.0);
    mad(vecX, x, vecY * y)
}
