/// Safety: latticeSelector covers256 bytes and noiseData covers4*256 packed u32
/// samples, both live/readable throughout execution. Every computed coordinate
/// passed to iround must satisfy native finite i32 conversion bounds. Context
/// memory must not alias output pixel writes or be mutated during execution.
pub unsafe fn perlin_noise(
    p: &mut Registers,
    ctx: &crate::src::core::SkRasterPipelineOpContexts::PerlinNoiseCtx,
) {
    use crate::src::shaders::SkPerlinNoiseShaderType::SkPerlinNoiseShaderType;
    // Scalar C++ uses the un-suffixed double literal0.5 in these two expressions.
    let mut noiseVecX = ((p.r as f64 + 0.5) * ctx.baseFrequencyX as f64) as f32;
    let mut noiseVecY = ((p.g as f64 + 0.5) * ctx.baseFrequencyY as f64) as f32;
    p.r = 0.;
    p.g = 0.;
    p.b = 0.;
    p.a = 0.;
    let mut stitchDataX = ctx.stitchDataInX;
    let mut stitchDataY = ctx.stitchDataInY;
    let mut ratio = 1.;
    for _octave in 0..ctx.numOctaves {
        let mut floorValX = floor_(noiseVecX);
        let mut floorValY = floor_(noiseVecY);
        let mut ceilValX = floorValX + 1.;
        let mut ceilValY = floorValY + 1.;
        let fractValX = noiseVecX - floorValX;
        let fractValY = noiseVecY - floorValY;
        if ctx.stitching {
            floorValX -= f32::from_bits(
                if floorValX >= stitchDataX {
                    u32::MAX
                } else {
                    0
                } & stitchDataX.to_bits(),
            );
            floorValY -= f32::from_bits(
                if floorValY >= stitchDataY {
                    u32::MAX
                } else {
                    0
                } & stitchDataY.to_bits(),
            );
            ceilValX -= f32::from_bits(
                if ceilValX >= stitchDataX { u32::MAX } else { 0 } & stitchDataX.to_bits(),
            );
            ceilValY -= f32::from_bits(
                if ceilValY >= stitchDataY { u32::MAX } else { 0 } & stitchDataY.to_bits(),
            );
        }
        let mut latticeLookup = iround(floorValX) as u32 & 0xff;
        let latticeIdxX = ctx.latticeSelector.add(latticeLookup as usize).read() as f32;
        latticeLookup = iround(ceilValX) as u32 & 0xff;
        let latticeIdxY = ctx.latticeSelector.add(latticeLookup as usize).read() as f32;
        let b00 = iround(latticeIdxX + floorValY) as u32 & 0xff;
        let b10 = iround(latticeIdxY + floorValY) as u32 & 0xff;
        let b01 = iround(latticeIdxX + ceilValY) as u32 & 0xff;
        let b11 = iround(latticeIdxY + ceilValY) as u32 & 0xff;
        let smoothX = fractValX * fractValX * (3. - 2. * fractValX);
        let smoothY = fractValY * fractValY * (3. - 2. * fractValY);
        let mut color = [core::mem::MaybeUninit::<f32>::uninit(); 4];
        let mut channelNoiseData = ctx.noiseData.cast::<u32>();
        for channel in 0..4 {
            let sample00 = channelNoiseData.add(b00 as usize).read_unaligned();
            let sample10 = channelNoiseData.add(b10 as usize).read_unaligned();
            let sample01 = channelNoiseData.add(b01 as usize).read_unaligned();
            let sample11 = channelNoiseData.add(b11 as usize).read_unaligned();
            channelNoiseData = channelNoiseData.add(256);
            let mut u = compute_perlin_vector(sample00, fractValX, fractValY);
            let mut v = compute_perlin_vector(sample10, fractValX - 1., fractValY);
            let a = lerp(u, v, smoothX);
            u = compute_perlin_vector(sample01, fractValX, fractValY - 1.);
            v = compute_perlin_vector(sample11, fractValX - 1., fractValY - 1.);
            let b = lerp(u, v, smoothX);
            color[channel].write(lerp(a, b, smoothY));
        }
        let mut color = color.map(|v| v.assume_init());
        if ctx.noiseType != SkPerlinNoiseShaderType::kFractalNoise {
            color[0] = abs_(color[0]);
            color[1] = abs_(color[1]);
            color[2] = abs_(color[2]);
            color[3] = abs_(color[3]);
        }
        p.r = mad(color[0], ratio, p.r);
        p.g = mad(color[1], ratio, p.g);
        p.b = mad(color[2], ratio, p.b);
        p.a = mad(color[3], ratio, p.a);
        noiseVecX *= 2.;
        noiseVecY *= 2.;
        stitchDataX *= 2.;
        stitchDataY *= 2.;
        ratio *= 0.5;
    }
    if ctx.noiseType == SkPerlinNoiseShaderType::kFractalNoise {
        p.r = mad(p.r, 0.5, 0.5);
        p.g = mad(p.g, 0.5, 0.5);
        p.b = mad(p.b, 0.5, 0.5);
        p.a = mad(p.a, 0.5, 0.5);
    }
    p.r = clamp_01_(p.r) * p.a;
    p.g = clamp_01_(p.g) * p.a;
    p.b = clamp_01_(p.b) * p.a;
    p.a = clamp_01_(p.a);
}
