/// Safety: c is a live stationary initializedCallbackCtx and its actual callback
/// satisfies the active-pixel/read_from lease contract. No callback access may
/// race another pipeline execution or reset/drop any participating owner.
pub unsafe fn callback(
    p: &mut Registers,
    c: *mut crate::src::core::SkRasterPipelineOpContexts::CallbackCtx,
) {
    let rgba = core::ptr::addr_of_mut!((*c).rgba).cast::<f32>();
    rgba.add(0).write(p.r);
    rgba.add(1).write(p.g);
    rgba.add(2).write(p.b);
    rgba.add(3).write(p.a);
    ((*c).r#fn)(c, SCALAR_N as i32);
    let read_from = core::ptr::addr_of!((*c).read_from).read();
    p.r = read_from.add(0).read();
    p.g = read_from.add(1).read();
    p.b = read_from.add(2).read();
    p.a = read_from.add(3).read();
}
