unsafe fn shuffle_fn<const LOOP: usize, O: Copy + Into<usize>>(
    ptr: *mut u8,
    offsets: *const O,
    numSlots: i32,
) {
    let mut scratch = [core::mem::MaybeUninit::<f32>::uninit(); 16];
    for count in 0..LOOP {
        scratch[count].write(
            ptr.add(offsets.add(count).read().into())
                .cast::<f32>()
                .read(),
        );
    }
    let dst = ptr.cast::<f32>();
    match numSlots {
        1..=16 => {
            for index in (0..numSlots as usize).rev() {
                dst.add(index).write(scratch[index].assume_init_read());
            }
        }
        _ => {}
    }
}
