macro_rules! unary_stages {
    ($ty:ty,$apply:ident,$one:ident,$two:ident,$three:ident,$four:ident) => {
        /// Safety: p addresses1..4 initialized native slots in a live aligned exclusive
        /// allocation. Float-to-int casts additionally require finite values whose
        /// truncated results are representable in the native target integer type.
        pub unsafe fn $one(p: *mut $ty) {
            apply_adjacent_unary(p, p.add(1), $apply);
        }
        pub unsafe fn $two(p: *mut $ty) {
            apply_adjacent_unary(p, p.add(2), $apply);
        }
        pub unsafe fn $three(p: *mut $ty) {
            apply_adjacent_unary(p, p.add(3), $apply);
        }
        pub unsafe fn $four(p: *mut $ty) {
            apply_adjacent_unary(p, p.add(4), $apply);
        }
    };
}
