// Source: src/opts/SkRasterPipeline_opts.h:4898-4906
unsafe fn apply_adjacent_binary<T>(
    mut dst: *mut T,
    mut src: *mut T,
    apply: unsafe fn(*mut T, *mut T),
) {
    let end = src;
    loop {
        apply(dst, src);
        dst = dst.add(1);
        src = src.add(1);
        if dst == end {
            break;
        }
    }
}
// Source: src/opts/SkRasterPipeline_opts.h:4908-4915
unsafe fn apply_adjacent_binary_packed<T>(
    packed: *const crate::src::core::SkRasterPipelineOpContexts::BinaryOpCtx,
    base: *mut u8,
    apply: unsafe fn(*mut T, *mut T),
) {
    use crate::src::core::SkRasterPipelineContextUtils::{Unpack, UnpackedType};
    let ctx = match Unpack(packed) {
        UnpackedType::Value(v) => v,
        UnpackedType::Borrowed(v) => *v,
    };
    let dst = base.add(ctx.dst as usize);
    let src = base.add(ctx.src as usize);
    apply_adjacent_binary(dst.cast(), src.cast(), apply);
}
// Source: src/opts/SkRasterPipeline_opts.h:4917-4927
unsafe fn apply_binary_immediate<const N: usize, T>(
    packed: *const crate::src::core::SkRasterPipelineOpContexts::ConstantCtx,
    base: *mut u8,
    decode: fn(i32) -> T,
    apply: unsafe fn(*mut T, *mut T),
) {
    use crate::src::core::SkRasterPipelineContextUtils::{Unpack, UnpackedType};
    let ctx = match Unpack(packed) {
        UnpackedType::Value(v) => v,
        UnpackedType::Borrowed(v) => *v,
    };
    let mut dst = base.add(ctx.dst as usize).cast::<T>();
    let mut src = decode(ctx.value);
    for _index in 0..N {
        apply(dst, &mut src);
        dst = dst.add(1);
    }
}
