macro_rules! binary_stages {
    ($ty:ty,$apply:ident,$one:ident,$two:ident,$three:ident,$four:ident,$many:ident) => {
        /// Safety: p covers two adjacent initialized arrays of the native slot count
        /// in one live aligned exclusive allocation; packed/base obey native layout.
        pub unsafe fn $one(p: *mut $ty) {
            apply_adjacent_binary(p, p.add(1), $apply);
        }
        pub unsafe fn $two(p: *mut $ty) {
            apply_adjacent_binary(p, p.add(2), $apply);
        }
        pub unsafe fn $three(p: *mut $ty) {
            apply_adjacent_binary(p, p.add(3), $apply);
        }
        pub unsafe fn $four(p: *mut $ty) {
            apply_adjacent_binary(p, p.add(4), $apply);
        }
        pub unsafe fn $many(
            c: *const crate::src::core::SkRasterPipelineOpContexts::BinaryOpCtx,
            b: *mut u8,
        ) {
            apply_adjacent_binary_packed(c, b, $apply);
        }
    };
}
