/// Safety: gather context and readable packed image cover all clamped addresses.
pub unsafe fn bilerp_clamp_large(p: &mut Registers, ctx: &GatherCtx) {
    let cx = p.r;
    let cy = p.g;
    let fx = fract(cx + 0.5);
    let fy = fract(cy + 0.5);
    p.r = 0.;
    p.g = 0.;
    p.b = 0.;
    p.a = 0.;
    let mut py = -0.5;
    while py <= 0.5 {
        let mut px = -0.5;
        while px <= 0.5 {
            let x = cx + px;
            let y = cy + py;
            let (ptr, ix) = ix_and_ptr::<u32>(ctx, x, y);
            let [sr, sg, sb, sa] = from_8888(ptr.add(ix as usize).read_unaligned());
            let sx = if px > 0. { fx } else { 1. - fx };
            let sy = if py > 0. { fy } else { 1. - fy };
            let area = sx * sy;
            p.r += sr * area;
            p.g += sg * area;
            p.b += sb * area;
            p.a += sa * area;
            px += 1.;
        }
        py += 1.;
    }
}
