/// Safety: gather context and readable image cover all clamped addresses.
pub unsafe fn bicubic_clamp_8888(p: &mut Registers, ctx: &GatherCtx) {
    let cx = p.r;
    let cy = p.g;
    let fx = fract(cx + 0.5);
    let fy = fract(cy + 0.5);
    p.r = 0.;
    p.g = 0.;
    p.b = 0.;
    p.a = 0.;
    let w = &ctx.weights;
    let scaley = [
        bicubic_wts(fy, w[0], w[4], w[8], w[12]),
        bicubic_wts(fy, w[1], w[5], w[9], w[13]),
        bicubic_wts(fy, w[2], w[6], w[10], w[14]),
        bicubic_wts(fy, w[3], w[7], w[11], w[15]),
    ];
    let scalex = [
        bicubic_wts(fx, w[0], w[4], w[8], w[12]),
        bicubic_wts(fx, w[1], w[5], w[9], w[13]),
        bicubic_wts(fx, w[2], w[6], w[10], w[14]),
        bicubic_wts(fx, w[3], w[7], w[11], w[15]),
    ];
    let mut sample_y = cy - 1.5;
    for yy in 0..=3 {
        let mut sample_x = cx - 1.5;
        for xx in 0..=3 {
            let scale = scalex[xx] * scaley[yy];
            let (ptr, ix) = ix_and_ptr::<u32>(ctx, sample_x, sample_y);
            let [sr, sg, sb, sa] = from_8888(ptr.add(ix as usize).read_unaligned());
            p.r = mad(scale, sr, p.r);
            p.g = mad(scale, sg, p.g);
            p.b = mad(scale, sb, p.b);
            p.a = mad(scale, sa, p.a);
            sample_x += 1.;
        }
        sample_y += 1.;
    }
}
// Source: src/opts/SkRasterPipeline_opts.h:5445-5463
pub fn swizzle(p: &mut Registers, ctx: *mut core::ffi::c_void) {
    let ir = p.r;
    let ig = p.g;
    let ib = p.b;
    let ia = p.a;
    let outputs = [&mut p.r, &mut p.g, &mut p.b, &mut p.a];
    let bytes = (ctx as usize).to_ne_bytes();
    for (i, out) in outputs.into_iter().enumerate() {
        match bytes[i] {
            b'r' => *out = ir,
            b'g' => *out = ig,
            b'b' => *out = ib,
            b'a' => *out = ia,
            b'0' => *out = 0.,
            b'1' => *out = 1.,
            _ => {}
        }
    }
}
