#[cfg(all(target_arch = "aarch64", target_feature = "neon"))]
pub mod neon_lowp_math {
    use super::neon_lowp_vectors as v;

    use super::{
        neon,
        neon_lowp::{F, F_},
    };

    // Source: src/opts/SkRasterPipeline_opts.h:5920-5934
    pub fn mad(f: F, m: F, a: F) -> F {
        unsafe {
            use core::arch::aarch64::*;
            let f: [float32x4_t; 2] = core::mem::transmute(f);
            let m: [float32x4_t; 2] = core::mem::transmute(m);
            let a: [float32x4_t; 2] = core::mem::transmute(a);
            core::mem::transmute([
                vaddq_f32(a[0], vmulq_f32(f[0], m[0])),
                vaddq_f32(a[1], vmulq_f32(f[1], m[1])),
            ])
        }
    }
    pub fn mad_vvf(f: F, m: F, a: f32) -> F {
        mad(f, m, F_(a))
    }
    pub fn mad_vfv(f: F, m: f32, a: F) -> F {
        mad(f, F_(m), a)
    }
    pub fn mad_vff(f: F, m: f32, a: f32) -> F {
        mad(f, F_(m), F_(a))
    }
    pub fn mad_fvv(f: f32, m: F, a: F) -> F {
        mad(F_(f), m, a)
    }
    pub fn mad_fvf(f: f32, m: F, a: f32) -> F {
        mad(F_(f), m, F_(a))
    }
    pub fn mad_ffv(f: f32, m: f32, a: F) -> F {
        mad(F_(f), F_(m), a)
    }
    pub fn nmad(f: F, m: F, a: F) -> F {
        unsafe {
            use core::arch::aarch64::*;
            let f: [float32x4_t; 2] = core::mem::transmute(f);
            let m: [float32x4_t; 2] = core::mem::transmute(m);
            let a: [float32x4_t; 2] = core::mem::transmute(a);
            core::mem::transmute([
                vsubq_f32(a[0], vmulq_f32(f[0], m[0])),
                vsubq_f32(a[1], vmulq_f32(f[1], m[1])),
            ])
        }
    }
    pub fn nmad_vvf(f: F, m: F, a: f32) -> F {
        nmad(f, m, F_(a))
    }
    pub fn nmad_vfv(f: F, m: f32, a: F) -> F {
        nmad(f, F_(m), a)
    }
    pub fn nmad_vff(f: F, m: f32, a: f32) -> F {
        nmad(f, F_(m), F_(a))
    }
    pub fn nmad_fvv(f: f32, m: F, a: F) -> F {
        nmad(F_(f), m, a)
    }
    pub fn nmad_fvf(f: f32, m: F, a: f32) -> F {
        nmad(F_(f), m, F_(a))
    }
    pub fn nmad_ffv(f: f32, m: f32, a: F) -> F {
        nmad(F_(f), F_(m), a)
    }
    // Source: src/opts/SkRasterPipeline_opts.h:5939-5966
    pub fn rcp_precise(x: F) -> F {
        // Bit-preserving split/join of the original eight-lane object.
        let [lo, hi]: [[f32; 4]; 2] = unsafe { core::mem::transmute(x) };
        v::join(&neon::rcp_precise(lo), &neon::rcp_precise(hi))
    }
    // Source: src/opts/SkRasterPipeline_opts.h:5967-6006
    pub fn sqrt_(x: F) -> F {
        let [lo, hi]: [[f32; 4]; 2] = unsafe { core::mem::transmute(x) };
        v::join(&neon::sqrt_(lo), &neon::sqrt_(hi))
    }
    // Source: src/opts/SkRasterPipeline_opts.h:6008-6035
    pub fn floor_(x: F) -> F {
        let [lo, hi]: [[f32; 4]; 2] = unsafe { core::mem::transmute(x) };
        v::join(&neon::floor_(lo), &neon::floor_(hi))
    }
    // Source: src/opts/SkRasterPipeline_opts.h:6042-6063
    pub fn scaled_mult(
        a: super::neon_lowp::I16,
        b: super::neon_lowp::I16,
    ) -> super::neon_lowp::I16 {
        unsafe {
            core::mem::transmute(core::arch::aarch64::vqrdmulhq_s16(
                core::mem::transmute(a),
                core::mem::transmute(b),
            ))
        }
    }

    // Source: src/opts/SkRasterPipeline_opts.h:6068-6081
    pub fn constrained_add(
        a: super::neon_lowp::I16,
        b: super::neon_lowp::U16,
    ) -> super::neon_lowp::U16 {
        #[cfg(sk_debug)]
        for i in 0..super::neon_lowp::N {
            let ia = a[i] as i32;
            let ib = b[i] as i32;
            crate::SkASSERT!(@source b"src/opts/SkRasterPipeline_opts.h\0".as_ptr(),6077; @condition b"-ib <= ia && ia <= 65535 - ib\0".as_ptr(); -ib<=ia&&ia<=65535-ib);
        }
        v::add(&b, &a.map(|x| x as u16))
    }
    // Source: src/opts/SkRasterPipeline_opts.h:6083-6083
    pub fn fract(x: F) -> F {
        unsafe {
            use core::arch::aarch64::*;
            let a: [float32x4_t; 2] = core::mem::transmute(x);
            let b: [float32x4_t; 2] = core::mem::transmute(floor_(x));
            core::mem::transmute([vsubq_f32(a[0], b[0]), vsubq_f32(a[1], b[1])])
        }
    }
    // Source: src/opts/SkRasterPipeline_opts.h:6084-6084
    pub fn abs_(x: F) -> F {
        x.map(|x| f32::from_bits(x.to_bits() & 0x7fff_ffff))
    }
}

/// Original lowp coordinate kernels; stage wrappers/runner remain pending.
#[cfg(all(target_arch = "aarch64", target_feature = "neon"))]
pub mod neon_lowp_geometry {
    use super::neon_lowp_vectors as v;

    use super::neon_lowp::{F, F_, I32_};
    use super::neon_lowp_math::{mad_vff, mad_vfv, rcp_precise};

    // Source: src/opts/SkRasterPipeline_opts.h:6088-6115
    pub fn seed_shader_k(dx: usize, dy: usize, x: &mut F, y: &mut F) {
        const IOTA: [f32; 16] = [
            0.5, 1.5, 2.5, 3.5, 4.5, 5.5, 6.5, 7.5, 8.5, 9.5, 10.5, 11.5, 12.5, 13.5, 14.5, 15.5,
        ];
        const {
            assert!(IOTA.len() >= crate::src::core::SkRasterPipelineOpContexts::kMaxStride);
        }
        *x = v::add(
            &v::cast::<8, f32, i32>(&I32_(dx as i32)),
            &IOTA[..8].try_into().unwrap(),
        );
        *y = v::add(&v::cast::<8, f32, i32>(&I32_(dy as i32)), &F_(0.5));
    }
    // Source: src/opts/SkRasterPipeline_opts.h:6117-6120
    pub fn matrix_translate_k(m: &[f32; 2], _dx: usize, _dy: usize, x: &mut F, y: &mut F) {
        *x = v::add(x, &F_(m[0]));
        *y = v::add(y, &F_(m[1]));
    }
    // Source: src/opts/SkRasterPipeline_opts.h:6121-6124
    pub fn matrix_scale_translate_k(m: &[f32; 4], _dx: usize, _dy: usize, x: &mut F, y: &mut F) {
        *x = mad_vff(*x, m[0], m[2]);
        *y = mad_vff(*y, m[1], m[3]);
    }
    // Source: src/opts/SkRasterPipeline_opts.h:6125-6130
    pub fn matrix_2x3_k(m: &[f32; 6], _dx: usize, _dy: usize, x: &mut F, y: &mut F) {
        let X = mad_vfv(*x, m[0], mad_vff(*y, m[1], m[2]));
        let Y = mad_vfv(*x, m[3], mad_vff(*y, m[4], m[5]));
        *x = X;
        *y = Y;
    }
    // Source: src/opts/SkRasterPipeline_opts.h:6131-6138
    pub fn matrix_perspective_k(m: &[f32; 9], _dx: usize, _dy: usize, x: &mut F, y: &mut F) {
        let X = mad_vfv(*x, m[0], mad_vff(*y, m[1], m[2]));
        let Y = mad_vfv(*x, m[3], mad_vff(*y, m[4], m[5]));
        let Z = mad_vfv(*x, m[6], mad_vff(*y, m[7], m[8]));
        *x = v::mul(&X, &rcp_precise(Z));
        *y = v::mul(&Y, &rcp_precise(Z));
    }
}

