        r = n::if_then_else_f32(neg, v::neg(&r), r);
        r = n::if_then_else_f32(
            v::bit_and(&v::cmp_ge(&y0, &F_(0.0)), &v::cmp_lt(&x0, &F_(0.0))),
            v::add(&r, &F_(PI)),
            r,
        );
