    /// Safety: all lanes of the original truncation argument fit signed32.
    pub unsafe fn exclusive_mirror(x: F, ctx: &TileCtx) -> F {
        let limit = F_(ctx.scale);
        let invLimit = F_(ctx.invScale);
        let u = v::sub(
            &x,
            &v::mul(
                &v::mul(
                    &n::floor_(v::mul(&v::mul(&x, &invLimit), &F_(0.5))),
                    &F_(2.0),
                ),
                &limit,
            ),
        );
        let s = n::floor_(v::mul(&u, &invLimit));
        let m = v::sub(&u, &v::mul(&v::mul(&F_(2.0), &s), &v::sub(&u, &limit)));
        let biasInUlps = n::trunc_(s);
        v::add(
            &m.map(f32::to_bits),
            &v::mul(
                &[ctx.mirrorBiasDir as u32; 4],
                &biasInUlps.map(|x| x as u32),
            ),
        )
        .map(f32::from_bits)
    }
