    /// Safety: LOOP is original1..4or16; numSlots0..LOOP. All LOOP offsets/read
    /// vectors initialized/aligned/live even when numSlots smaller. Destination
    /// vector writes exclusively leased; original all-read-before-descending-write.
    pub unsafe fn shuffle_fn<const LOOP: usize, O: Copy + Into<usize>>(
        ptr: *mut u8,
        offsets: *const O,
        numSlots: i32,
    ) {
        let mut scratch = [core::mem::MaybeUninit::<F>::uninit(); 16];
        for count in 0..LOOP {
            scratch[count].write(ptr.add(offsets.add(count).read().into()).cast::<F>().read());
        }
        let dst = ptr.cast::<F>();
        match numSlots {
            1..=16 => {
                for index in (0..numSlots as usize).rev() {
                    dst.add(index).write(scratch[index].assume_init_read());
                }
            }
            _ => { /* Original switch: no matching case, no writes. */ }
        }
    }
    // Source: src/opts/SkRasterPipeline_opts.h:4584-4587
    /// Safety: original N1..4, canonicalpackedctx, frame ranges for N source and
    /// destination vectors live/initialized/aligned; exclusive destination access.
    pub unsafe fn small_swizzle<const N: usize>(packed: *const SwizzleCtx, base: *mut u8) {
        let ctx = match Unpack(packed) {
            UnpackedType::Value(c) => c,
            UnpackedType::Borrowed(c) => *c,
        };
        shuffle_fn::<N, u8>(base.add(ctx.dst as usize), ctx.offsets.as_ptr(), N as i32);
    }
    // Source: src/opts/SkRasterPipeline_opts.h:4606-4614
    /// Safety: original N1..4; offsets and N source/destination vectors valid,
    /// initialized/aligned/live/exclusive asappropriate. Sequential aliasorder kept.
    pub unsafe fn swizzle_copy_masked<const N: usize>(
        dst: *mut I32,
        mut src: *const I32,
        mut offsets: *const u16,
        mask: I32,
    ) {
        let dstB = dst.cast::<u8>();
        for count in 0..N {
            let dstS = dstB.add(offsets.read() as usize).cast::<I32>();
            dstS.write(n::if_then_else_i32(mask, src.read(), dstS.read()));
            offsets = offsets.add(1);
            src = src.add(1);
        }
    }
