    unsafe fn div_int(dst: *mut I32, src: *mut I32) {
        let x = dst.read();
        let mut divisor = src.read();
        divisor = v::bit_or(&divisor, &v::cmp_eq(&divisor, &[0; 4]));
        let overflow = v::bit_and(
            &v::cmp_eq(&divisor, &[-1; 4]),
            &v::cmp_eq(&x, &[i32::MIN; 4]),
        );
        divisor = v::add(&divisor, &overflow);
        dst.write(v::div(&x, &divisor));
    }
