                    let mut a = [0u8; 16];
                    let mut b = [0u8; 16];
                    core::ptr::copy_nonoverlapping(
                        x.as_ptr().cast::<u8>(),
                        a.as_mut_ptr(),
                        core::mem::size_of_val(&x),
                    );
                    core::ptr::copy_nonoverlapping(
                        y.as_ptr().cast::<u8>(),
                        b.as_mut_ptr(),
                        core::mem::size_of_val(&y),
                    );
                    let a = _mm_loadu_si128(a.as_ptr().cast());
                    let b = _mm_loadu_si128(b.as_ptr().cast());
                    let z = match kind {
                        0 => _mm_and_si128(a, b),
                        1 => _mm_or_si128(a, b),
                        2 => _mm_xor_si128(a, b),
                        _ => unreachable!(),
                    };
                    core::ptr::addr_of!(z).cast::<[Self; 4]>().read_unaligned()
