    pub fn strip_sign(x: F, sign: &mut U32) -> F {
        let bits = x.map(f32::to_bits);
        *sign = v::bit_and(&bits, &U32_(0x80000000));
        v::bit_xor(&bits, sign).map(f32::from_bits)
    }
    // Source: src/opts/SkRasterPipeline_opts.h:2996-2998
    pub fn apply_sign(x: F, sign: U32) -> F {
        v::bit_or(&sign, &x.map(f32::to_bits)).map(f32::from_bits)
    }
