        let a02 = dst.add(2).read();
        let a10 = dst.add(3).read();
        let a11 = dst.add(4).read();
        let a12 = dst.add(5).read();
        let a20 = dst.add(6).read();
        let a21 = dst.add(7).read();
        let a22 = dst.add(8).read();
        let b01 = n::nmad(a12, a21, v::mul(&a22, &a11));
        let b11 = n::nmad(a22, a10, v::mul(&a12, &a20));
        let b21 = n::nmad(a11, a20, v::mul(&a21, &a10));
        let det = n::mad(a00, b01, n::mad(a01, b11, v::mul(&a02, &b21)));
        let invdet = n::rcp_precise(det);
        dst.add(0).write(v::mul(&invdet, &b01));
        dst.add(1)
            .write(v::mul(&invdet, &n::nmad(a22, a01, v::mul(&a02, &a21))));
        dst.add(2)
            .write(v::mul(&invdet, &n::nmad(a02, a11, v::mul(&a12, &a01))));
        dst.add(3).write(v::mul(&invdet, &b11));
        dst.add(4)
