    /// Safety: N is native1..4; canonical packed context, aligned initialized
    /// live exclusive destination frame ranges, disjoint from regs/ctx/program.
    unsafe fn immediate<const N: usize, T: Copy>(
        packed: *const ConstantCtx,
        base: *mut u8,
        scalar: unsafe fn(u32) -> T,
        apply: unsafe fn(*mut T, *mut T),
    ) {
        let ctx = match Unpack(packed) {
            UnpackedType::Value(c) => c,
            UnpackedType::Borrowed(c) => *c,
        };
        let mut dst = base.add(ctx.dst as usize).cast::<T>();
        let mut src = scalar(ctx.value as u32);
        for index in 0..N {
            apply(dst, &mut src);
            dst = dst.add(1);
        }
    }
    // Integer scalar minus zero-vector broadcast: exactly native modulo32 arithmetic.
    unsafe fn signed(x: u32) -> I32 {
        [x as i32; 4]
    }
    unsafe fn unsigned(x: u32) -> U32 {
        [x; 4]
    }
