        offsets = v::add(&offsets, &IOTA.as_ptr().cast::<U32>().read_unaligned());
        let mut src = common.src;
        let mut dst = common.dst.cast::<I32>();
        let end = dst.add(common.slots as usize);
        loop {
            dst.write(n::gather_unaligned(src, offsets));
            dst = dst.add(1);
            src = src.add(8);
            if dst == end {
                break;
            }
        }
