    // Source: src/opts/SkRasterPipeline_opts.h:4898-4906
    /// Safety: initialized aligned vectors in one live frame; src follows dst by
    /// a positive whole-vector distance. Both full ranges are initialized; dst
    /// exclusively leased and disjoint from registers/program/context.
    unsafe fn adjacent<T: Copy>(
        mut dst: *mut T,
        mut src: *mut T,
        apply: unsafe fn(*mut T, *mut T),
    ) {
        let end = src;
        loop {
            apply(dst, src);
            dst = dst.add(1);
            src = src.add(1);
            if dst == end {
                break;
            }
        }
    }
    // Source: src/opts/SkRasterPipeline_opts.h:4908-4915
    unsafe fn packed<T: Copy>(
        ctx: *const BinaryOpCtx,
        base: *mut u8,
        apply: unsafe fn(*mut T, *mut T),
    ) {
        let c = match Unpack(ctx) {
            UnpackedType::Value(c) => c,
            UnpackedType::Borrowed(c) => *c,
        };
        adjacent(
            base.add(c.dst as usize).cast(),
            base.add(c.src as usize).cast(),
            apply,
        );
    }
