    unsafe fn max_uint(dst: *mut U32, src: *mut U32) {
        let x = dst.read();
        let y = src.read();
        let mask = v::cmp_gt(&x, &y).map(|x| x as i32);
        dst.write(
            n::if_then_else_i32(mask, x.map(|x| x as i32), y.map(|x| x as i32)).map(|x| x as u32),
        );
    }
