    pub unsafe fn to_unorm(x: F, scale: f32, bias: f32, maxI: i32) -> U32 {
        n::round(n::min_f32(
            n::max_f32(F_(0.0), n::mad(x, F_(scale), F_(bias))),
            F_(maxI as f32),
        ))
    }
    // Source: src/opts/SkRasterPipeline_opts.h:2273-2275
    pub unsafe fn to_unorm_scale(x: F, scale: i32) -> U32 {
        to_unorm(x, scale as f32, 0.0, scale)
    }
