    /// Safety: sampler arrays initialized/live/exclusive, disjoint from y;
    /// K is an original instantiated scale (-1/+1 bilinear, -3/-1/+1/+3 bicubic).
    pub unsafe fn bilinear_y<const K: i32>(ctx: &mut SamplerCtx, y: &mut F) {
        *y = v::add(&load::<F, f32>(ctx.y.as_ptr()), &F_(K as f32 * 0.5));
        let fy = load::<F, f32>(ctx.fy.as_ptr());
        let scaley = if K == -1 { v::sub(&F_(1.0), &fy) } else { fy };
        store(ctx.scaley.as_mut_ptr(), scaley);
    }
