#[cfg(any(target_arch = "x86", target_arch = "x86_64"))]
pub mod x86_ml4_base {
    #![allow(unused_variables)]

    use super::x86_ml4::F;
    use super::x86_ml4_vectors as v;
    use crate::src::core::{
        SkRasterPipelineContextUtils::{Unpack, UnpackedType},
        SkRasterPipelineOpContexts::CaseOpCtx,
    };
    // Source: src/opts/SkRasterPipeline_opts.h:4194-4196
    /// Safety: the program's later base-relative accesses must have actual
    /// live aligned initialized/exclusive frame leases. Pointer identity alone
    /// confers no lifetime or access guarantee; this stage only assigns opaque bits.
    pub unsafe fn set_base_pointer_k(
        p: *mut u8,
        base: &mut *mut u8,
        dx: usize,
        dy: usize,
        r: &mut F,
        g: &mut F,
        b: &mut F,
        a: &mut F,
        dr: &mut F,
        dg: &mut F,
        db: &mut F,
        da: &mut F,
    ) {
        *base = p;
    }
    // Source: src/opts/SkRasterPipeline_opts.h:4304-4318
    /// Safety: packed is the canonical Pack<CaseOpCtx> result. The active base
    /// belongs to a live exclusive aligned frame with two initialized I32 vectors
    /// at the unpacked byte offset; frame/context/program/register storage disjoint.
    pub unsafe fn case_op_k(
        packed: *const CaseOpCtx,
        base: *mut u8,
        dx: usize,
        dy: usize,
        r: &mut F,
        g: &mut F,
        b: &mut F,
        a: &mut F,
        dr: &mut F,
        dg: &mut F,
        db: &mut F,
        da: &mut F,
    ) {
        let ctx = match Unpack(packed) {
            UnpackedType::Value(ctx) => ctx,
            UnpackedType::Borrowed(ctx) => *ctx,
        };
        let actualValue = base.add(ctx.offset as usize).cast::<[i32; 16]>();
        let caseMatches = v::cmp_eq(&actualValue.read(), &[ctx.expectedValue; 16]);
        *g = v::bit_or(&g.map(|x| x.to_bits() as i32), &caseMatches)
            .map(|x| f32::from_bits(x as u32));
        super::x86_ml4_masks::update_execution_mask(*r, *g, *b, a);
        let defaultMask = actualValue.add(1);
        defaultMask.write(v::bit_and(&defaultMask.read(), &caseMatches.map(|x| !x)));
    }
}

