    /// no singularmatrix/defaultresult substitute.
    pub unsafe fn inverse_mat2_k(
        dst: *mut F,
        dx: usize,
        dy: usize,
        r: &mut F,
        g: &mut F,
        b: &mut F,
        a: &mut F,
        dr: &mut F,
        dg: &mut F,
        db: &mut F,
        da: &mut F,
    ) {
        let a00 = dst.add(0).read();
        let a01 = dst.add(1).read();
        let a10 = dst.add(2).read();
        let a11 = dst.add(3).read();
        let det = n::nmad(a01, a10, v::mul(&a00, &a11));
        let invdet = n::rcp_precise(det);
        dst.add(0).write(v::mul(&invdet, &a11));
        dst.add(1).write(v::mul(&v::neg(&invdet), &a01));
        dst.add(2).write(v::mul(&v::neg(&invdet), &a10));
        dst.add(3).write(v::mul(&invdet, &a00));
    }
