        b05 = v::mul(&b05, &invdet);
        b06 = v::mul(&b06, &invdet);
        b07 = v::mul(&b07, &invdet);
        b08 = v::mul(&b08, &invdet);
        b09 = v::mul(&b09, &invdet);
        b10 = v::mul(&b10, &invdet);
        b11 = v::mul(&b11, &invdet);
