        dst.add(8)
            .write(n::mad(a13, b06, n::nmad(a11, b08, v::mul(&a10, &b10))));
        dst.add(9)
            .write(n::nmad(a03, b06, n::nmad(a00, b10, v::mul(&a01, &b08))));
        dst.add(10)
            .write(n::mad(a33, b00, n::nmad(a31, b02, v::mul(&a30, &b04))));
        dst.add(11)
            .write(n::nmad(a23, b00, n::nmad(a20, b04, v::mul(&a21, &b02))));
        dst.add(12)
            .write(n::nmad(a12, b06, n::nmad(a10, b09, v::mul(&a11, &b07))));
        dst.add(13)
            .write(n::mad(a02, b06, n::nmad(a01, b07, v::mul(&a00, &b09))));
        dst.add(14)
            .write(n::nmad(a32, b00, n::nmad(a30, b03, v::mul(&a31, &b01))));
        dst.add(15)
            .write(n::mad(a22, b00, n::nmad(a21, b01, v::mul(&a20, &b03))));
