    /// Safety: canonical packed context, aligned initialized live exclusive
    /// destination vector in frame, disjoint from regs/program/context.
    unsafe fn immediate(
        packed: *const ConstantCtx,
        base: *mut u8,
        apply: unsafe fn(*mut F, *mut F),
    ) {
        let ctx = match Unpack(packed) {
            UnpackedType::Value(c) => c,
            UnpackedType::Borrowed(c) => *c,
        };
        let dst = base.add(ctx.dst as usize).cast::<F>();
        let scalar = f32::from_bits(ctx.value as u32);
        let mut src = v::sub(&[scalar; 16], &[0.; 16]);
        apply(dst, &mut src);
    }
