    #![allow(unused_variables)]

    // Source: src/opts/SkRasterPipeline_opts.h:6239-6270
    // Preserve the actual native build-time accuracy policy; this is not a
    // missing-stage fallback. Both branches use the selected ISA's vector math.
    unsafe fn blend_div255(v: U16) -> U16 {
        if cfg!(SK_USE_INACCURATE_DIV255_IN_BLEND) {
            div255(v)
        } else {
            div255_accurate(v)
        }
    }
    use super::x86_sse_lowp_vectors as v;
    // Source: src/opts/SkRasterPipeline_opts.h:6219-6224
