#[cfg(any(target_arch = "x86", target_arch = "x86_64"))]
pub mod x86_avx2_lowp_geometry {
    use super::x86_avx2_lowp_vectors as v;

    use super::x86_avx2_lowp::{F, F_, I32_};
    use super::x86_avx2_lowp_math::{mad_vff, mad_vfv, rcp_precise};

    // Source: src/opts/SkRasterPipeline_opts.h:6088-6115
    pub unsafe fn seed_shader_k(dx: usize, dy: usize, x: &mut F, y: &mut F) {
        const IOTA: [f32; 16] = [
            0.5, 1.5, 2.5, 3.5, 4.5, 5.5, 6.5, 7.5, 8.5, 9.5, 10.5, 11.5, 12.5, 13.5, 14.5, 15.5,
        ];
        const {
            assert!(IOTA.len() >= crate::src::core::SkRasterPipelineOpContexts::kMaxStride);
        }
        *x = v::add(
            &v::cast::<16, f32, i32>(&I32_(dx as i32)),
            &IOTA[..16].try_into().unwrap(),
        );
        *y = v::add(&v::cast::<16, f32, i32>(&I32_(dy as i32)), &F_(0.5));
    }
    // Source: src/opts/SkRasterPipeline_opts.h:6117-6120
    pub unsafe fn matrix_translate_k(m: &[f32; 2], _dx: usize, _dy: usize, x: &mut F, y: &mut F) {
        *x = v::add(x, &F_(m[0]));
        *y = v::add(y, &F_(m[1]));
    }
    // Source: src/opts/SkRasterPipeline_opts.h:6121-6124
    pub unsafe fn matrix_scale_translate_k(
        m: &[f32; 4],
        _dx: usize,
        _dy: usize,
        x: &mut F,
        y: &mut F,
    ) {
        *x = mad_vff(*x, m[0], m[2]);
        *y = mad_vff(*y, m[1], m[3]);
    }
    // Source: src/opts/SkRasterPipeline_opts.h:6125-6130
    pub unsafe fn matrix_2x3_k(m: &[f32; 6], _dx: usize, _dy: usize, x: &mut F, y: &mut F) {
        let X = mad_vfv(*x, m[0], mad_vff(*y, m[1], m[2]));
        let Y = mad_vfv(*x, m[3], mad_vff(*y, m[4], m[5]));
        *x = X;
        *y = Y;
    }
    // Source: src/opts/SkRasterPipeline_opts.h:6131-6138
    pub unsafe fn matrix_perspective_k(m: &[f32; 9], _dx: usize, _dy: usize, x: &mut F, y: &mut F) {
        let X = mad_vfv(*x, m[0], mad_vff(*y, m[1], m[2]));
        let Y = mad_vfv(*x, m[3], mad_vff(*y, m[4], m[5]));
        let Z = mad_vfv(*x, m[6], mad_vff(*y, m[7], m[8]));
        *x = v::mul(&X, &rcp_precise(Z));
        *y = v::mul(&Y, &rcp_precise(Z));
    }
}

