#[cfg(any(target_arch = "x86", target_arch = "x86_64"))]
pub mod x86_avx2_lowp_gradient {
    #![allow(unused_variables)]

    use super::x86_avx2_lowp::{F, F_, U16, U32, U32_};
    use super::x86_avx2_lowp_decal::round_F_to_U16;
    use super::x86_avx2_lowp_math::{mad, mad_vff};
    use super::x86_avx2_lowp_memory::{gather, trunc_};
    use super::x86_avx2_lowp_select::if_then_else_u32;
    use super::x86_avx2_lowp_vectors as v;
    use crate::src::core::SkRasterPipelineOpContexts::{EvenlySpaced2StopGradientCtx, GradientCtx};
    // Source: src/opts/SkRasterPipeline_opts.h:6956-7046
    /// Safety: each of4 aligned factor/bias arrays is live/readable at every idx.
    /// Resulting alpha mad(t,factorA,biasA) must be finite in[0,1]. Calls are
    /// synchronous and retain no array,context or pixel pointer.
    pub unsafe fn gradient_lookup(
        c: &GradientCtx,
        idx: U32,
        t: F,
        r: &mut U16,
        g: &mut U16,
        b: &mut U16,
        a: &mut U16,
    ) {
        let channels: [[u16; 16]; 4] = core::mem::transmute(super::x86_lowp::gradient_lookup(
            c,
            core::mem::transmute(idx),
            core::mem::transmute(t),
        ));
        [*r, *g, *b, *a] = channels;
    }
    // Source: src/opts/SkRasterPipeline_opts.h:7048-7058
    /// Safety: stopCount is nonzero;ts[0..stopCount] and all4 factor/bias arrays
    /// are aligned/live/readable. All resulting indexed alpha values meet the
    /// original finite[0,1] invariant required by gradient_lookup.
    pub unsafe fn gradient_k(
        c: &GradientCtx,
        dx: usize,
        dy: usize,
        x: F,
        y: F,
        r: &mut U16,
        g: &mut U16,
        b: &mut U16,
        a: &mut U16,
    ) {
        let t = x;
        let mut idx = U32_(0);
        for i in 1..c.stopCount {
            idx = v::add(
                &idx,
                &if_then_else_u32(v::cmp_ge(&t, &F_(c.ts.add(i).read())), U32_(1), U32_(0)),
            );
        }
        gradient_lookup(c, idx, t, r, g, b, a);
    }
    // Source: src/opts/SkRasterPipeline_opts.h:7060-7064
    /// Safety: stopCount is nonzero;the original t*(stopCount-1) signed truncation
    /// is defined and every resulting index is in the live factor/bias arrays.
    /// Resulting alpha is finite in[0,1],as required by gradient_lookup.
    pub unsafe fn evenly_spaced_gradient_k(
        c: &GradientCtx,
        dx: usize,
        dy: usize,
        x: F,
        y: F,
        r: &mut U16,
        g: &mut U16,
        b: &mut U16,
        a: &mut U16,
    ) {
        let t = x;
        let idx = trunc_(v::mul(&t, &F_((c.stopCount - 1) as f32)));
        gradient_lookup(c, idx, t, r, g, b, a);
    }
    // Source: src/opts/SkRasterPipeline_opts.h:7066-7074
    /// Safety: each resulting alpha mad(x,factorA,biasA) is finite in[0,1].
    pub unsafe fn evenly_spaced_2_stop_gradient_k(
        c: &EvenlySpaced2StopGradientCtx,
        dx: usize,
        dy: usize,
        x: F,
        y: F,
        r: &mut U16,
        g: &mut U16,
        b: &mut U16,
        a: &mut U16,
    ) {
        let t = x;
        round_F_to_U16(
            mad_vff(t, c.factor[0], c.bias[0]),
            mad_vff(t, c.factor[1], c.bias[1]),
            mad_vff(t, c.factor[2], c.bias[2]),
            mad_vff(t, c.factor[3], c.bias[3]),
            r,
            g,
            b,
            a,
        );
    }
}

