pub mod x86_avx2_lowp_bilerp {
    #![allow(non_snake_case, unused_variables)]

    use super::x86_avx2_lowp::{F, F_, I32_, U16, U16_};
    use super::x86_avx2_lowp_8888::from_8888;
    use super::x86_avx2_lowp_math::{constrained_add, floor_, scaled_mult};
    use super::x86_avx2_lowp_memory::{gather_unaligned, ix_and_ptr_i32};
    use super::x86_avx2_lowp_vectors as v;
    use crate::src::core::SkRasterPipelineOpContexts::GatherCtx;
    // Source: src/opts/SkRasterPipeline_opts.h:7076-7198
    /// Safety: each coordinate's floor(65536*c+0.5) conversion and following
    /// signed32768 subtraction are defined in native i32. The original context's
    /// dimensions admit integer ix_and_ptr conversion and roundDownAtInteger is
    /// false. All clamped corner indices span live/readable RGBA8888 pixels,
    /// disjoint from output registers;this call retains no source/destination lease.
    pub unsafe fn bilerp_clamp_8888_k(
        ctx: &GatherCtx,
        dx: usize,
        dy: usize,
        x: F,
        y: F,
        r: &mut U16,
        g: &mut U16,
        b: &mut U16,
        a: &mut U16,
    ) {
        let qx = v::sub(
            &v::cast::<16, i32, f32>(&floor_(v::add(&v::mul(&F_(65536.0), &x), &F_(0.5)))),
            &I32_(32768),
        );
        let qy = v::sub(
            &v::cast::<16, i32, f32>(&floor_(v::add(&v::mul(&F_(65536.0), &y), &F_(0.5)))),
            &I32_(32768),
        );
        let sx = v::shr(&qx, 16);
        let sy = v::shr(&qy, 16);
        let tx = v::cast::<16, i16, i32>(&v::bit_xor(&qx, &I32_(0x8000)));
        let ty = v::cast::<16, i16, i32>(&v::bit_xor(&qy, &I32_(0x8000)));
        let lerpX = |left: U16, right: U16| -> U16 {
            let width = v::shl(&v::cast::<16, i16, u16>(&v::sub(&right, &left)), 7);
            let middle = v::shl(&v::add(&right, &left), 7);
            let v2 = v::add(&constrained_add(scaled_mult(tx, width), middle), &U16_(1));
            v::shr(&v2, 1)
        };
        let (ptr, ix) = ix_and_ptr_i32::<u32>(ctx, sx, sy);
        let (mut leftR, mut leftG, mut leftB, mut leftA) =
            ([0u16; 16], [0u16; 16], [0u16; 16], [0u16; 16]);
        from_8888(
            gather_unaligned::<u32, u32>(ptr, ix),
            &mut leftR,
            &mut leftG,
            &mut leftB,
            &mut leftA,
        );
        let (ptr, ix) = ix_and_ptr_i32::<u32>(ctx, v::add(&sx, &I32_(1)), sy);
        let (mut rightR, mut rightG, mut rightB, mut rightA) =
            ([0u16; 16], [0u16; 16], [0u16; 16], [0u16; 16]);
        from_8888(
            gather_unaligned::<u32, u32>(ptr, ix),
            &mut rightR,
            &mut rightG,
            &mut rightB,
            &mut rightA,
        );
        let topR = lerpX(leftR, rightR);
        let topG = lerpX(leftG, rightG);
        let topB = lerpX(leftB, rightB);
        let topA = lerpX(leftA, rightA);
        let (ptr, ix) = ix_and_ptr_i32::<u32>(ctx, sx, v::add(&sy, &I32_(1)));
        from_8888(
            gather_unaligned::<u32, u32>(ptr, ix),
            &mut leftR,
            &mut leftG,
            &mut leftB,
            &mut leftA,
        );
        let (ptr, ix) = ix_and_ptr_i32::<u32>(ctx, v::add(&sx, &I32_(1)), v::add(&sy, &I32_(1)));
        from_8888(
            gather_unaligned::<u32, u32>(ptr, ix),
            &mut rightR,
            &mut rightG,
            &mut rightB,
            &mut rightA,
        );
        let bottomR = lerpX(leftR, rightR);
        let bottomG = lerpX(leftG, rightG);
        let bottomB = lerpX(leftB, rightB);
        let bottomA = lerpX(leftA, rightA);
        let lerpY = |top: U16, bottom: U16| -> U16 {
            let width = v::sub(
                &v::cast::<16, i16, u16>(&bottom),
                &v::cast::<16, i16, u16>(&top),
            );
            let middle = v::add(&bottom, &top);
            let blend = v::add(
                &constrained_add(scaled_mult(ty, width), middle),
                &U16_(0x80),
            );
            v::shr(&blend, 8)
        };
        *r = lerpY(topR, bottomR);
        *g = lerpY(topG, bottomG);
        *b = lerpY(topB, bottomB);
        *a = lerpY(topA, bottomA);
    }
}

#[cfg(any(target_arch = "x86", target_arch = "x86_64"))]
pub mod x86_avx2_lowp_misc {
    #![allow(unused_variables)]

    use super::x86_avx2_lowp::{div255, inv, F, F_, U16, U16_0, U16_255};
    use super::x86_avx2_lowp_8888::{load_8888_, store_8888_};
    use super::x86_avx2_lowp_math::{abs_, sqrt_};
    use super::x86_avx2_lowp_memory::ptr_at_xy;
    use super::x86_avx2_lowp_select::{if_then_else_f32, max_f32, min_f32};
    use super::x86_avx2_lowp_vectors as v;
    use crate::src::core::SkRasterPipelineOpContexts::MemoryCtx;
    // Source: src/opts/SkRasterPipeline_opts.h:7200-7222
    pub unsafe fn xy_to_unit_angle_k(_ctx: (), dx: usize, dy: usize, x: &mut F, y: &mut F) {
        let xabs = abs_(*x);
        let yabs = abs_(*y);
        let slope = v::div(&min_f32(xabs, yabs), &max_f32(xabs, yabs));
        let s = v::mul(&slope, &slope);
        let mut phi = v::mul(
            &slope,
            &v::add(
                &F_(0.15912117063999176025390625),
                &v::mul(
                    &s,
                    &v::add(
                        &F_(-5.185396969318389892578125e-2),
                        &v::mul(
                            &s,
                            &v::add(
                                &F_(2.476101927459239959716796875e-2),
                                &v::mul(&s, &F_(-7.0547382347285747528076171875e-3)),
                            ),
                        ),
                    ),
                ),
            ),
        );
        phi = if_then_else_f32(v::cmp_lt(&xabs, &yabs), v::sub(&F_(1.0 / 4.0), &phi), phi);
        phi = if_then_else_f32(v::cmp_lt(x, &F_(0.0)), v::sub(&F_(1.0 / 2.0), &phi), phi);
        phi = if_then_else_f32(v::cmp_lt(y, &F_(0.0)), v::sub(&F_(1.0), &phi), phi);
        phi = if_then_else_f32(v::cmp_ne(&phi, &phi), F_(0.0), phi);
        *x = phi;
    }
    // Source: src/opts/SkRasterPipeline_opts.h:7223-7225
    pub unsafe fn xy_to_radius_k(_ctx: (), dx: usize, dy: usize, x: &mut F, y: &mut F) {
        *x = sqrt_(v::add(&v::mul(x, x), &v::mul(y, y)));
    }
    // Source: src/opts/SkRasterPipeline_opts.h:7229-7238
    /// Safety: ctx addresses8 live readable/exclusively writable RGBA8888 pixels,
    /// disjoint from output registers;the lease lasts through synchronous load+store.
    pub unsafe fn srcover_rgba_8888_k(
        ctx: &MemoryCtx,
        dx: usize,
        dy: usize,
        r: &mut U16,
        g: &mut U16,
        b: &mut U16,
        a: &mut U16,
        dr: &mut U16,
        dg: &mut U16,
        db: &mut U16,
        da: &mut U16,
    ) {
        let ptr = ptr_at_xy::<u32>(ctx, dx, dy);
        load_8888_(ptr, dr, dg, db, da);
        *r = v::add(r, &div255(v::mul(dr, &inv(*a))));
        *g = v::add(g, &div255(v::mul(dg, &inv(*a))));
        *b = v::add(b, &div255(v::mul(db, &inv(*a))));
        *a = v::add(a, &div255(v::mul(da, &inv(*a))));
        store_8888_(ptr, *r, *g, *b, *a);
    }
    // Source: src/opts/SkRasterPipeline_opts.h:7242-7259
    /// ctx's first4 pointer-representation bytes encode the swizzle itself;ctx is
    /// not a dereferenceable address and no storage lease derives from its value.
    pub unsafe fn swizzle_k(
        ctx: *mut core::ffi::c_void,
        dx: usize,
        dy: usize,
        r: &mut U16,
        g: &mut U16,
        b: &mut U16,
        a: &mut U16,
        dr: &mut U16,
        dg: &mut U16,
        db: &mut U16,
        da: &mut U16,
    ) {
        let (ir, ig, ib, ia) = (*r, *g, *b, *a);
        let outputs = [r, g, b, a];
        let swiz = (ctx as usize).to_ne_bytes();
        for (i, out) in outputs.into_iter().enumerate() {
            match swiz[i] {
                b'r' => *out = ir,
                b'g' => *out = ig,
                b'b' => *out = ib,
                b'a' => *out = ia,
                b'0' => *out = U16_0,
                b'1' => *out = U16_255,
                _ => {}
            }
        }
    }
}

