    pub unsafe fn store_8888_(ptr: *mut u32, mut r: U16, mut g: U16, mut b: U16, mut a: U16) {
        r = min_u16_vs(r, 255);
        g = min_u16_vs(g, 255);
        b = min_u16_vs(b, 255);
        a = min_u16_vs(a, 255);
        let lo = v::cast::<16, u32, u16>(&v::bit_or(&r, &v::shl(&g, 8)));
        let hi = v::shl(&v::cast::<16, u32, u16>(&v::bit_or(&b, &v::shl(&a, 8))), 16);
        super::x86_ml4_lowp_memory::store(ptr, v::bit_or(&lo, &hi));
    }
