    use super::x86_sse41_vectors as v;

    use super::x86_sse41::{self as n, F, F_, I32, U32, U32_};
    use crate::src::core::SkRasterPipelineOpContexts::GatherCtx;
    // Namespace reuse of identical generic unaligned-byte and rowpointer bodies;
    // these helpers carry no lane count or retained storage lifetime.
    pub use super::x86_sse41_memory::{load, ptr_at_xy, store};
    // Source: src/opts/SkRasterPipeline_opts.h:2085-2088
    pub unsafe fn clamp(x: F, limit: F) -> F {
        let inclusive = v::sub(&limit.map(f32::to_bits), &U32_(1)).map(f32::from_bits);
        n::min_f32(n::max_f32(F_(0.0), x), inclusive)
    }
    // Source: src/opts/SkRasterPipeline_opts.h:2091-2095
    pub unsafe fn clamp_ex(x: F, limit: f32) -> F {
        let inclusiveZ = F_(f32::MIN_POSITIVE);
        let inclusiveL = v::sub(&F_(limit).map(f32::to_bits), &U32_(1)).map(f32::from_bits);
        n::min_f32(n::max_f32(inclusiveZ, x), inclusiveL)
    }
    // Source: src/opts/SkRasterPipeline_opts.h:2247-2256
    /// Safety: after original exclusive clamps/bit decrement,both coordinates
    /// have defined native signed-i32 float conversion. Dimensions/stride retain
    /// the original valid image domain. Returned rawpointer/index implies no
    /// readable image lease;gather callers must separately prove every span.
    pub unsafe fn ix_and_ptr<T>(ctx: &GatherCtx, mut x: F, mut y: F) -> (*const T, U32) {
        x = clamp_ex(x, ctx.width);
        y = clamp_ex(y, ctx.height);
        x = v::sub(&x.map(f32::to_bits), &U32_(ctx.roundDownAtInteger as u32)).map(f32::from_bits);
        y = v::sub(&y.map(f32::to_bits), &U32_(ctx.roundDownAtInteger as u32)).map(f32::from_bits);
        let ptr = ctx.pixels.cast::<T>();
        (
            ptr,
            v::add(
                &v::mul(&n::trunc_(y), &U32_(ctx.stride as u32)),
                &n::trunc_(x),
            ),
        )
    }
