    /// RecursiveC++stackmechanicsareadaptedintoexecute'sinplaceiteration.
    pub unsafe fn stack_checkpoint(program: *mut Stage, s: &mut State) -> *mut Stage {
        let c = (*program).ctx.cast::<RewindCtx>();
        assert!(
            s.rewind.is_null() || s.rewind == c,
            "different nested checkpoint contexts are unsupported"
        );
        s.rewind = c;
        (*c).stage = core::ptr::null_mut();
        program.add(1)
    }
