    pub unsafe fn decal_y_k(ctx: &mut DecalTileCtx, dx: usize, dy: usize, x: &mut F, y: &mut F) {
        let h = ctx.limit_y;
        let mask = cond_to_mask_16(v::bit_and(&v::cmp_le(&F_(0.0), y), &v::cmp_lt(y, &F_(h))));
        unsafe {
            store(ctx.mask.as_mut_ptr(), mask);
        }
    }
