    /// Safety: each of4 aligned factor/bias arrays is live/readable at every idx.
    /// Resulting alpha mad(t,factorA,biasA) must be finite in[0,1]. Calls are
    /// synchronous and retain no array,context or pixel pointer.
    pub unsafe fn gradient_lookup(
        c: &GradientCtx,
        idx: U32,
        t: F,
        r: &mut U16,
        g: &mut U16,
        b: &mut U16,
        a: &mut U16,
    ) {
        let fr = gather::<f32, f32>(c.factors[0], idx);
        let fg = gather::<f32, f32>(c.factors[1], idx);
        let fb = gather::<f32, f32>(c.factors[2], idx);
        let fa = gather::<f32, f32>(c.factors[3], idx);
        let br = gather::<f32, f32>(c.biases[0], idx);
        let bg = gather::<f32, f32>(c.biases[1], idx);
        let bb = gather::<f32, f32>(c.biases[2], idx);
        let ba = gather::<f32, f32>(c.biases[3], idx);
        round_F_to_U16(
            mad(t, fr, br),
            mad(t, fg, bg),
            mad(t, fb, bb),
            mad(t, fa, ba),
            r,
            g,
            b,
            a,
        );
    }
