    /// Safety: sampler arrays initialized/live/exclusive, disjoint from x;
    /// K is an original instantiated scale (-1/+1 bilinear, -3/-1/+1/+3 bicubic).
    pub unsafe fn bilinear_x<const K: i32>(ctx: &mut SamplerCtx, x: &mut F) {
        *x = v::add(&load::<F, f32>(ctx.x.as_ptr()), &F_(K as f32 * 0.5));
        let fx = load::<F, f32>(ctx.fx.as_ptr());
        let scalex = if K == -1 { v::sub(&F_(1.0), &fx) } else { fx };
        store(ctx.scalex.as_mut_ptr(), scalex);
    }
    // Source: src/opts/SkRasterPipeline_opts.h:3963-3971
    /// Safety: sampler arrays initialized/live/exclusive, disjoint from y;
