pub mod x86_avx_perlin {
    #![allow(unused_variables, non_snake_case)]

    use super::x86_avx::{self as n, F, F_, U32};
    use super::x86_avx_coverage::lerp;
    use super::x86_avx_sampling_helpers::{load, store};
    use super::x86_avx_vectors as v;
    use crate::src::core::SkRasterPipelineOpContexts::{MipmapCtx, PerlinNoiseCtx};
    use crate::src::shaders::SkPerlinNoiseShaderType::SkPerlinNoiseShaderType;
    // Source: src/opts/SkRasterPipeline_opts.h:4048-4049
    // Source: src/opts/SkRasterPipeline_opts.h:4054-4065
    pub unsafe fn compute_perlin_vector(sample: U32, x: F, y: F) -> F {
        #[cfg(target_endian = "little")]
        let (sampleLo, sampleHi) = (v::bit_and(&sample, &[65535u32; 4]), v::shr(&sample, 16));
        // Source: src/opts/SkRasterPipeline_opts.h:4051-4052
        #[cfg(target_endian = "big")]
        let (sampleLo, sampleHi) = (v::shr(&sample, 16), v::bit_and(&sample, &[65535u32; 4]));
        let vecX = n::mad(n::cast(sampleLo), F_(2.0 / 65535.0), F_(-1.0));
        let vecY = n::mad(n::cast(sampleHi), F_(2.0 / 65535.0), F_(-1.0));
        n::mad(vecX, x, v::mul(&vecY, &y))
    }
    // Source: src/opts/SkRasterPipeline_opts.h:4067-4164
    /// Safety: context and pointed arrays are initialized/live and disjoint
    /// from all registers; numeric/index domains hold for every lane and octave.
    /// Mutable context arrays require exclusive synchronous access.
    pub unsafe fn perlin_noise_k(
        ctx: &PerlinNoiseCtx,
        dx: usize,
        dy: usize,
        r: &mut F,
        g: &mut F,
        b: &mut F,
        a: &mut F,
        dr: &mut F,
        dg: &mut F,
        db: &mut F,
        da: &mut F,
    ) {
        let mut noiseVecX = v::mul(&v::add(r, &F_(0.5)), &F_(ctx.baseFrequencyX));
        let mut noiseVecY = v::mul(&v::add(g, &F_(0.5)), &F_(ctx.baseFrequencyY));
        *r = F_(0.0);
        *g = F_(0.0);
        *b = F_(0.0);
        *a = F_(0.0);
        let mut stitchDataX = F_(ctx.stitchDataInX);
        let mut stitchDataY = F_(ctx.stitchDataInY);
        let mut ratio = F_(1.0);
        for octave in 0..ctx.numOctaves {
            let mut floorValX = n::floor_(noiseVecX);
            let mut floorValY = n::floor_(noiseVecY);
            let mut ceilValX = v::add(&floorValX, &F_(1.0));
            let mut ceilValY = v::add(&floorValY, &F_(1.0));
            let fractValX = v::sub(&noiseVecX, &floorValX);
            let fractValY = v::sub(&noiseVecY, &floorValY);
            if ctx.stitching {
                floorValX = v::sub(
                    &floorValX,
                    &v::bit_and(
                        &v::cmp_ge(&floorValX, &stitchDataX).map(|x| x as u32),
                        &stitchDataX.map(f32::to_bits),
                    )
                    .map(f32::from_bits),
                );
                floorValY = v::sub(
                    &floorValY,
                    &v::bit_and(
                        &v::cmp_ge(&floorValY, &stitchDataY).map(|x| x as u32),
                        &stitchDataY.map(f32::to_bits),
                    )
                    .map(f32::from_bits),
                );
                ceilValX = v::sub(
                    &ceilValX,
                    &v::bit_and(
                        &v::cmp_ge(&ceilValX, &stitchDataX).map(|x| x as u32),
                        &stitchDataX.map(f32::to_bits),
                    )
                    .map(f32::from_bits),
                );
                ceilValY = v::sub(
                    &ceilValY,
                    &v::bit_and(
                        &v::cmp_ge(&ceilValY, &stitchDataY).map(|x| x as u32),
                        &stitchDataY.map(f32::to_bits),
                    )
                    .map(f32::from_bits),
                );
            }
            let latticeLookup = v::bit_and(&n::iround(floorValX).map(|x| x as u32), &[255u32; 4]);
            let latticeIdxX = n::cast(n::expand_u8(n::gather_unaligned(
                ctx.latticeSelector,
                latticeLookup,
            )));
            let latticeLookup = v::bit_and(&n::iround(ceilValX).map(|x| x as u32), &[255u32; 4]);
            let latticeIdxY = n::cast(n::expand_u8(n::gather_unaligned(
                ctx.latticeSelector,
                latticeLookup,
            )));
            let b00 = v::bit_and(
                &n::iround(v::add(&latticeIdxX, &floorValY)).map(|x| x as u32),
                &[255u32; 4],
            );
            let b10 = v::bit_and(
                &n::iround(v::add(&latticeIdxY, &floorValY)).map(|x| x as u32),
                &[255u32; 4],
            );
            let b01 = v::bit_and(
                &n::iround(v::add(&latticeIdxX, &ceilValY)).map(|x| x as u32),
                &[255u32; 4],
            );
            let b11 = v::bit_and(
                &n::iround(v::add(&latticeIdxY, &ceilValY)).map(|x| x as u32),
                &[255u32; 4],
            );
            let smoothX = v::mul(
                &v::mul(&fractValX, &fractValX),
                &v::sub(&F_(3.0), &v::mul(&F_(2.0), &fractValX)),
            );
            let smoothY = v::mul(
                &v::mul(&fractValY, &fractValY),
                &v::sub(&F_(3.0), &v::mul(&F_(2.0), &fractValY)),
            );
            let mut color = [F_(0.0); 4];
            let mut channelNoiseData = ctx.noiseData.cast::<u32>();
            for channel in 0..4 {
                let sample00 = n::gather_unaligned(channelNoiseData, b00);
                let sample10 = n::gather_unaligned(channelNoiseData, b10);
                let sample01 = n::gather_unaligned(channelNoiseData, b01);
                let sample11 = n::gather_unaligned(channelNoiseData, b11);
                channelNoiseData = channelNoiseData.add(256);
                let u = compute_perlin_vector(sample00, fractValX, fractValY);
                let v0 = compute_perlin_vector(sample10, v::sub(&fractValX, &F_(1.0)), fractValY);
                let A = lerp(u, v0, smoothX);
                let u = compute_perlin_vector(sample01, fractValX, v::sub(&fractValY, &F_(1.0)));
                let v0 = compute_perlin_vector(
                    sample11,
                    v::sub(&fractValX, &F_(1.0)),
                    v::sub(&fractValY, &F_(1.0)),
                );
                let B = lerp(u, v0, smoothX);
                color[channel] = lerp(A, B, smoothY);
            }
            if ctx.noiseType != SkPerlinNoiseShaderType::kFractalNoise {
                color[0] = n::abs_f32(color[0]);
                color[1] = n::abs_f32(color[1]);
                color[2] = n::abs_f32(color[2]);
                color[3] = n::abs_f32(color[3]);
            }
            *r = n::mad(color[0], ratio, *r);
            *g = n::mad(color[1], ratio, *g);
            *b = n::mad(color[2], ratio, *b);
            *a = n::mad(color[3], ratio, *a);
            noiseVecX = v::mul(&noiseVecX, &F_(2.0));
            noiseVecY = v::mul(&noiseVecY, &F_(2.0));
            stitchDataX = v::mul(&stitchDataX, &F_(2.0));
            stitchDataY = v::mul(&stitchDataY, &F_(2.0));
            ratio = v::mul(&ratio, &F_(0.5));
        }
        if ctx.noiseType == SkPerlinNoiseShaderType::kFractalNoise {
            *r = n::mad(*r, F_(0.5), F_(0.5));
            *g = n::mad(*g, F_(0.5), F_(0.5));
            *b = n::mad(*b, F_(0.5), F_(0.5));
            *a = n::mad(*a, F_(0.5), F_(0.5));
        }
        *r = v::mul(&super::x86_avx_basic::clamp_01_(*r), a);
        *g = v::mul(&super::x86_avx_basic::clamp_01_(*g), a);
        *b = v::mul(&super::x86_avx_basic::clamp_01_(*b), a);
        *a = super::x86_avx_basic::clamp_01_(*a);
    }
    // Source: src/opts/SkRasterPipeline_opts.h:4166-4169
    /// Safety: context and pointed arrays are initialized/live and disjoint
    /// from all registers; numeric/index domains hold for every lane and octave.
    /// Mutable context arrays require exclusive synchronous access.
    pub unsafe fn mipmap_linear_init_k(
        ctx: &mut MipmapCtx,
        dx: usize,
        dy: usize,
        r: &mut F,
        g: &mut F,
        b: &mut F,
        a: &mut F,
        dr: &mut F,
        dg: &mut F,
        db: &mut F,
        da: &mut F,
    ) {
        store(ctx.x.as_mut_ptr(), *r);
        store(ctx.y.as_mut_ptr(), *g);
    }
    // Source: src/opts/SkRasterPipeline_opts.h:4171-4179
    /// Safety: context and pointed arrays are initialized/live and disjoint
    /// from all registers; numeric/index domains hold for every lane and octave.
    /// Mutable context arrays require exclusive synchronous access.
    pub unsafe fn mipmap_linear_update_k(
        ctx: &mut MipmapCtx,
        dx: usize,
        dy: usize,
        r: &mut F,
        g: &mut F,
        b: &mut F,
        a: &mut F,
        dr: &mut F,
        dg: &mut F,
        db: &mut F,
        da: &mut F,
    ) {
        store(ctx.r.as_mut_ptr(), *r);
        store(ctx.g.as_mut_ptr(), *g);
        store(ctx.b.as_mut_ptr(), *b);
        store(ctx.a.as_mut_ptr(), *a);
        *r = v::mul(&load::<F, f32>(ctx.x.as_ptr()), &F_(ctx.scaleX));
        *g = v::mul(&load::<F, f32>(ctx.y.as_ptr()), &F_(ctx.scaleY));
    }
    // Source: src/opts/SkRasterPipeline_opts.h:4181-4186
    /// Safety: context and pointed arrays are initialized/live and disjoint
    /// from all registers; numeric/index domains hold for every lane and octave.
    /// Mutable context arrays require exclusive synchronous access.
    pub unsafe fn mipmap_linear_finish_k(
        ctx: &MipmapCtx,
        dx: usize,
        dy: usize,
        r: &mut F,
        g: &mut F,
        b: &mut F,
        a: &mut F,
        dr: &mut F,
        dg: &mut F,
        db: &mut F,
        da: &mut F,
    ) {
        *r = lerp(load::<F, f32>(ctx.r.as_ptr()), *r, F_(ctx.lowerWeight));
        *g = lerp(load::<F, f32>(ctx.g.as_ptr()), *g, F_(ctx.lowerWeight));
        *b = lerp(load::<F, f32>(ctx.b.as_ptr()), *b, F_(ctx.lowerWeight));
        *a = lerp(load::<F, f32>(ctx.a.as_ptr()), *a, F_(ctx.lowerWeight));
    }
}

