    // Source: src/opts/SkRasterPipeline_opts.h:4552-4581
    /// Safety: LOOP is original1..4or16; numSlots0..LOOP. All LOOP offsets/read
    /// vectors initialized/aligned/live even when numSlots smaller. Destination
    /// vector writes exclusively leased; original all-read-before-descending-write.
    pub unsafe fn shuffle_fn<const LOOP: usize, O: Copy + Into<usize>>(
        ptr: *mut u8,
        offsets: *const O,
        numSlots: i32,
    ) {
        let mut scratch = [core::mem::MaybeUninit::<F>::uninit(); 16];
        for count in 0..LOOP {
            scratch[count].write(ptr.add(offsets.add(count).read().into()).cast::<F>().read());
        }
        let dst = ptr.cast::<F>();
        match numSlots {
            1..=16 => {
                for index in (0..numSlots as usize).rev() {
                    dst.add(index).write(scratch[index].assume_init_read());
                }
            }
            _ => { /* Original switch: no matching case, no writes. */ }
        }
    }
