    // Source: src/opts/SkRasterPipeline_opts.h:4898-4906
    /// Safety: same live initialized aligned frame with src a positive whole
    /// vector distance after dst. Full src/dst spans valid; dst exclusive and
    /// disjoint from registers/program/context. Original sequential writes kept.
    unsafe fn adjacent(mut dst: *mut F, mut src: *mut F, apply: unsafe fn(*mut F, *mut F)) {
        let end = src;
        loop {
            apply(dst, src);
            dst = dst.add(1);
            src = src.add(1);
            if dst == end {
                break;
            }
        }
    }
    // Source: src/opts/SkRasterPipeline_opts.h:4908-4915
    unsafe fn packed(ctx: *const BinaryOpCtx, base: *mut u8, apply: unsafe fn(*mut F, *mut F)) {
        let c = match Unpack(ctx) {
            UnpackedType::Value(c) => c,
            UnpackedType::Borrowed(c) => *c,
        };
        adjacent(
            base.add(c.dst as usize).cast(),
            base.add(c.src as usize).cast(),
            apply,
        );
    }
