pub mod x86_avx_additional_math {
    #![allow(unused_variables)]

    use super::x86_avx::{self as n, F};
    use super::x86_avx_vectors as v;
    // Source: src/opts/SkRasterPipeline_opts.h:5227-5246
    /// Safety: ninealignedinitializedliveframevectors,first4exclusive/disjoint
    /// fromremaining5andallregisters/program/context. Originaleta/k/sqrtbranch.
    pub unsafe fn refract_4_floats_k(
        dst: *mut F,
        dx: usize,
        dy: usize,
        r: &mut F,
        g: &mut F,
        b: &mut F,
        a: &mut F,
        dr: &mut F,
        dg: &mut F,
        db: &mut F,
        da: &mut F,
    ) {
        let incident = dst;
        let normal = dst.add(4);
        let eta = dst.add(8).read();
        let dotNI = n::mad(
            normal.add(0).read(),
            incident.add(0).read(),
            n::mad(
                normal.add(1).read(),
                incident.add(1).read(),
                n::mad(
                    normal.add(2).read(),
                    incident.add(2).read(),
                    v::mul(&normal.add(3).read(), &incident.add(3).read()),
                ),
            ),
        );
        let k = v::sub(
            &[1.; 4],
            &v::mul(
                &v::mul(&eta, &eta),
                &v::sub(&[1.; 4], &v::mul(&dotNI, &dotNI)),
            ),
        );
        let sqrt_k = n::sqrt_(k);
        for idx in 0..4 {
            dst.add(idx).write(n::if_then_else_f32(
                k.map(|x| if x >= 0. { -1 } else { 0 }),
                v::sub(
                    &v::mul(&eta, &incident.add(idx).read()),
                    &v::mul(
                        &v::add(&v::mul(&eta, &dotNI), &sqrt_k),
                        &normal.add(idx).read(),
                    ),
                ),
                [0.; 4],
            ));
        }
    }
    // Source: src/opts/SkRasterPipeline_opts.h:5326-5340
    pub unsafe fn gauss_a_to_rgba_k(
        dx: usize,
        dy: usize,
        r: &mut F,
        g: &mut F,
        b: &mut F,
        a: &mut F,
        dr: &mut F,
        dg: &mut F,
        db: &mut F,
        da: &mut F,
    ) {
        let c4 = [-2.26661229133605957031f32; 4];
        let c3 = [2.89795351028442382812f32; 4];
        let c2 = [0.21345567703247070312f32; 4];
        let c1 = [0.15489584207534790039f32; 4];
        let c0 = [0.00030726194381713867f32; 4];
        *a = n::mad(*a, n::mad(*a, n::mad(*a, n::mad(*a, c4, c3), c2), c1), c0);
        *r = *a;
        *g = *a;
        *b = *a;
    }
}

