    // Source: src/opts/SkRasterPipeline_opts.h:5490-5497,5736-5754
    // Compiler vector operations lower at the native x86 register width. Float
    // lowp vectors span two AVX2/SSE2 registers or one ML4 register, exactly as
    // native; U16 spans a single native128/256 register.
    pub trait Add: Copy {
        unsafe fn op(x: [Self; 8], y: [Self; 8]) -> [Self; 8];
    }
    pub trait Sub: Copy {
        unsafe fn op(x: [Self; 8], y: [Self; 8]) -> [Self; 8];
    }
    pub trait Mul: Copy {
        unsafe fn op(x: [Self; 8], y: [Self; 8]) -> [Self; 8];
    }
    pub trait Div: Copy {
        unsafe fn op(x: [Self; 8], y: [Self; 8]) -> [Self; 8];
    }
    pub trait Bit: Copy {
        unsafe fn op(x: [Self; 8], y: [Self; 8], kind: u8) -> [Self; 8];
    }
    pub trait Shift: Copy {
        unsafe fn op(x: [Self; 8], k: i32, right: bool) -> [Self; 8];
    }
    pub trait Cmp: Copy {
        type Mask: Copy;
        unsafe fn op(x: [Self; 8], y: [Self; 8], kind: u8) -> [Self::Mask; 8];
    }
    pub trait Select: Copy {
        type Mask: Copy;
        unsafe fn op(x: [Self; 8], y: [Self; 8], c: [Self::Mask; 8]) -> [Self; 8];
    }
