#[cfg(all(target_arch = "arm", target_feature = "neon"))]
pub mod neon_arm32_lowp_math {
    use core::arch::arm::*;
    pub type F = [float32x4_t; 2];
    // Source: src/opts/SkRasterPipeline_opts.h:5983-5991
    #[target_feature(enable = "neon")]
    pub unsafe fn sqrt_(x: F) -> F {
        unsafe fn sqrt(v: float32x4_t) -> float32x4_t {
            let mut est = vrsqrteq_f32(v);
            est = vmulq_f32(est, vrsqrtsq_f32(v, vmulq_f32(est, est)));
            est = vmulq_f32(est, vrsqrtsq_f32(v, vmulq_f32(est, est)));
            vmulq_f32(v, est)
        }
        [sqrt(x[0]), sqrt(x[1])]
    }
}

