// This is only the native non-ISA fallback branch, whose original body already
// calls scalar sqrtf eight times. No SIMD backend delegates to this function.
pub mod lowp_native_sqrt_fallback {
    #[cfg_attr(target_family = "unix", link(name = "m"))]
    extern "C" {
        fn sqrtf(v: f32) -> f32;
    }
    // Source: src/opts/SkRasterPipeline_opts.h:6001-6004
    pub fn sqrt_(x: [f32; 8]) -> [f32; 8] {
        unsafe {
            [
                sqrtf(x[0]),
                sqrtf(x[1]),
                sqrtf(x[2]),
                sqrtf(x[3]),
                sqrtf(x[4]),
                sqrtf(x[5]),
                sqrtf(x[6]),
                sqrtf(x[7]),
            ]
        }
    }
}

