    pub unsafe fn split<T: Copy, const L: usize, const H: usize>(
        value: [T; L],
    ) -> ([T; H], [T; H]) {
        const {
            assert!(L == 2 * H);
        }
        (
            value.as_ptr().cast::<[T; H]>().read_unaligned(),
            value.as_ptr().add(H).cast::<[T; H]>().read_unaligned(),
        )
    }
    pub unsafe fn join<T: Copy, const H: usize, const L: usize>(lo: [T; H], hi: [T; H]) -> [T; L] {
        const {
            assert!(L == 2 * H);
        }
        let mut value = core::mem::MaybeUninit::<[T; L]>::uninit();
        core::ptr::copy_nonoverlapping(lo.as_ptr(), value.as_mut_ptr().cast::<T>(), H);
        core::ptr::copy_nonoverlapping(hi.as_ptr(), value.as_mut_ptr().cast::<T>().add(H), H);
        value.assume_init()
    }

