    pub trait CastLane<D>: Copy {
        unsafe fn vector(x: [Self; 16]) -> [D; 16];
        unsafe fn gather(p: *const Self, ix: [u32; 16], unaligned: bool) -> [D; 16] {
            let values = core::array::from_fn(|j| {
                if unaligned {
                    p.add(ix[j] as usize).read_unaligned()
                } else {
                    p.add(ix[j] as usize).read()
                }
            });
            Self::vector(values)
        }
    }
    pub unsafe fn cast<const L: usize, D: Copy, S: CastLane<D>>(x: &[S; L]) -> [D; L] {
        const {
            assert!(L == 16);
        }
        let x = x.as_ptr().cast::<[S; 16]>().read_unaligned();
        let y = S::vector(x);
        y.as_ptr().cast::<[D; L]>().read_unaligned()
    }
