    // Source: src/opts/SkRasterPipeline_opts.h:2518-2518
    pub unsafe fn sat(r: F, g: F, b: F) -> F {
        v::sub(
            &n::max_f32(r, n::max_f32(g, b)),
            &n::min_f32(r, n::min_f32(g, b)),
        )
    }
    // Source: src/opts/SkRasterPipeline_opts.h:2519-2519
    pub unsafe fn lum(r: F, g: F, b: F) -> F {
        n::mad(r, F_(0.30), n::mad(g, F_(0.59), v::mul(&b, &F_(0.11))))
    }
    // Source: src/opts/SkRasterPipeline_opts.h:2521-2531
    pub unsafe fn set_sat(r: &mut F, g: &mut F, b: &mut F, mut s: F) {
        let mn = n::min_f32(*r, n::min_f32(*g, *b));
        let mx = n::max_f32(*r, n::max_f32(*g, *b));
        let sat = v::sub(&mx, &mn);
        s = n::if_then_else_f32(
            v::cmp_eq(&sat, &F_(0.0)),
            F_(0.0),
            v::mul(&s, &n::rcp_fast(sat)),
        );
        *r = v::mul(&v::sub(r, &mn), &s);
        *g = v::mul(&v::sub(g, &mn), &s);
        *b = v::mul(&v::sub(b, &mn), &s);
    }
    // Source: src/opts/SkRasterPipeline_opts.h:2532-2537
    pub unsafe fn set_lum(r: &mut F, g: &mut F, b: &mut F, l: F) {
        let diff = v::sub(&l, &lum(*r, *g, *b));
        *r = v::add(r, &diff);
        *g = v::add(g, &diff);
        *b = v::add(b, &diff);
    }
