    pub unsafe fn clip_channel(
        mut c: F,
        l: F,
        clip_low: I32,
        clip_high: I32,
        mn_scale: F,
        mx_scale: F,
    ) -> F {
        c = n::if_then_else_f32(clip_low, n::mad(mn_scale, v::sub(&c, &l), l), c);
        c = n::if_then_else_f32(clip_high, n::mad(mx_scale, v::sub(&c, &l), l), c);
        c = n::max_f32(c, F_(0.0));
        c
    }
    // Source: src/opts/SkRasterPipeline_opts.h:2544-2556
    pub unsafe fn clip_color(r: &mut F, g: &mut F, b: &mut F, a: F) {
        let mn = n::min_f32(*r, n::min_f32(*g, *b));
        let mx = n::max_f32(*r, n::max_f32(*g, *b));
        let l = lum(*r, *g, *b);
        let mn_scale = v::mul(&l, &n::rcp_fast(v::sub(&l, &mn)));
        let mx_scale = v::mul(&v::sub(&a, &l), &n::rcp_fast(v::sub(&mx, &l)));
        let clip_low = v::bit_and(&v::cmp_lt(&mn, &F_(0.0)), &v::cmp_ne(&l, &mn));
        let clip_high = v::bit_and(&v::cmp_gt(&mx, &a), &v::cmp_ne(&l, &mx));
        *r = clip_channel(*r, l, clip_low, clip_high, mn_scale, mx_scale);
        *g = clip_channel(*g, l, clip_low, clip_high, mn_scale, mx_scale);
        *b = clip_channel(*b, l, clip_low, clip_high, mn_scale, mx_scale);
    }
