    pub unsafe fn branch_if_any_lanes_active_k(
        ctx: &BranchCtx,
        dx: usize,
        dy: usize,
        r: &mut F,
        g: &mut F,
        b: &mut F,
        a: &mut F,
        dr: &mut F,
        dg: &mut F,
        db: &mut F,
        da: &mut F,
    ) -> isize {
        if n::any(a.map(|x| x.to_bits() as i32)) {
            ctx.offset as isize
        } else {
            1
        }
    }
    // Source: src/opts/SkRasterPipeline_opts.h:4348-4350
    /// Safety: live aligned context/readvectors/tail leases, disjoint from
    /// registers. A caller applying the returned signedoffset to PC must resolve
