#[cfg(target_arch = "loongarch64")]
pub mod lasx_pipe_lowp {
    use super::lasx_pipe_lowp_vectors as v;

    // Source: src/opts/SkRasterPipeline_opts.h:5490-5497
    // Adapted canonical array storage, without Clang vector alignment/ABI claims.
    pub type U8 = [u8; 16];
    pub type U16 = [u16; 16];
    pub type I16 = [i16; 16];
    pub type I32 = [i32; 16];
    pub type U32 = [u32; 16];
    pub type I64 = [i64; 16];
    pub type U64 = [u64; 16];
    pub type F = [f32; 16];
    // Source: src/opts/SkRasterPipeline_opts.h:5499-5499
    pub const N: usize = core::mem::size_of::<U16>() / core::mem::size_of::<u16>();
    // Source: src/opts/SkRasterPipeline_opts.h:5503-5506
    pub const fn U16_(x: u16) -> U16 {
        [x; 16]
    }
    pub const fn I32_(x: i32) -> I32 {
        [x; 16]
    }
    pub const fn U32_(x: u32) -> U32 {
        [x; 16]
    }
    pub const fn F_(x: f32) -> F {
        [x; 16]
    }
    // Source: src/opts/SkRasterPipeline_opts.h:5514-5515
    pub const U16_0: U16 = U16_(0);
    pub const U16_255: U16 = U16_(255);
    // Source: src/opts/SkRasterPipeline_opts.h:5705-5714
    pub unsafe fn div255(v: U16) -> U16 {
        v::shr(&v::add(&v, &U16_(255)), 8)
    }
    // Source: src/opts/SkRasterPipeline_opts.h:5719-5728
    pub unsafe fn div255_accurate(v: U16) -> U16 {
        let v = v::add(&v, &U16_(128));
        v::shr(&v::add(&v, &v::shr(&v, 8)), 8)
    }
    // Source: src/opts/SkRasterPipeline_opts.h:5730-5730
    pub unsafe fn inv(v: U16) -> U16 {
        v::sub(&U16_(255), &v)
    }
    // Source: src/opts/SkRasterPipeline_opts.h:5732-5732
    /// Safety: f*255+0.5 must be finite and its truncated value representable in
    /// u16, the defined domain of the original scalar float-to-uint16 conversion.
    pub unsafe fn from_float(f: f32) -> U16 {
        U16_((f * 255.0 + 0.5).to_int_unchecked::<u16>())
    }
    // Source: src/opts/SkRasterPipeline_opts.h:5734-5734
    pub unsafe fn lerp(from: U16, to: U16, t: U16) -> U16 {
        div255(v::add(&v::mul(&from, &inv(t)), &v::mul(&to, &t)))
    }
}

