#[cfg(target_arch = "loongarch64")]
pub mod lasx_pipe_lowp_memory {
    use super::lasx_pipe_lowp_vectors as v;

    use super::{
        lasx_pipe,
        lasx_pipe_lowp::{F, F_, I32, I32_, U32},
        lasx_pipe_lowp_select::{max_intr_f32, max_intr_i32, min_intr_f32, min_intr_i32},
    };
    use crate::src::core::SkRasterPipelineOpContexts::{GatherCtx, MemoryCtx};
    // Source: src/opts/SkRasterPipeline_opts.h:5936-5936
    /// Safety: every lane is finite and its truncated result is representable in
    /// original signed i32, required by the original builtin vector conversion.
    pub unsafe fn trunc_(x: F) -> U32 {
        let x: [[f32; 8]; 2] = core::mem::transmute(x);
        core::mem::transmute(core::array::from_fn::<[u32; 8], 2, _>(|j| {
            super::lasx_pipe::trunc_(x[j])
        }))
    }
    // Source: src/opts/SkRasterPipeline_opts.h:6301-6303
    /// Safety: ctx pixels retains the provenance of the pixel or patchscratch
    /// allocation. Its temporary tail fakebase maylieoutside thatallocation;
    /// wrapping_add cancels the exactrow/column displacement without requiring
    /// the fakebase itself inbounds. Only the finaladdress maybedereferenced,
    /// witha live initialized/exclusive span andalignment forits actualaccess.
    /// Merelyreturningthis pointer provesno storage/aliasing/length lease.
    pub unsafe fn ptr_at_xy<T>(ctx: &MemoryCtx, dx: usize, dy: usize) -> *mut T {
        ctx.pixels
            .cast::<T>()
            .wrapping_add(dy.wrapping_mul(ctx.stride as usize).wrapping_add(dx))
    }
    // Source: src/opts/SkRasterPipeline_opts.h:6306-6321
    /// Safety: width/height are finite native image dimensions at least1, with
    /// inclusive bounds in signed i32 conversion range. Pointer returned only
    /// identifies ctx pixels; caller separately proves live indexed pixel spans.
    pub unsafe fn ix_and_ptr_f32<T>(ctx: &GatherCtx, mut x: F, mut y: F) -> (*const T, U32) {
        let w = F_(f32::from_bits(ctx.width.to_bits().wrapping_sub(1)));
        let h = F_(f32::from_bits(ctx.height.to_bits().wrapping_sub(1)));
        let z = F_(f32::MIN_POSITIVE);
        x = min_intr_f32(max_intr_f32(z, x), w);
        y = min_intr_f32(max_intr_f32(z, y), h);
        x = x.map(|x| f32::from_bits(x.to_bits().wrapping_sub(ctx.roundDownAtInteger as u32)));
        y = y.map(|y| f32::from_bits(y.to_bits().wrapping_sub(ctx.roundDownAtInteger as u32)));
        let indices = v::add(&v::mul(&trunc_(y), &[ctx.stride as u32; 16]), &trunc_(x));
        (ctx.pixels.cast::<T>(), indices)
    }
    // Source: src/opts/SkRasterPipeline_opts.h:6324-6336
    /// Safety: width-1 and height-1 are finite and representable in native i32.
    /// Returned indices/pointer establish no live pixel span or aliasing lease.
    pub unsafe fn ix_and_ptr_i32<T>(ctx: &GatherCtx, x: I32, y: I32) -> (*const T, U32) {
        debug_assert!(!ctx.roundDownAtInteger);
        let w = I32_((ctx.width - 1.0).to_int_unchecked::<i32>());
        let h = I32_((ctx.height - 1.0).to_int_unchecked::<i32>());
        let ax = v::cast::<16, u32, i32>(&min_intr_i32(max_intr_i32(I32_(0), x), w));
        let ay = v::cast::<16, u32, i32>(&min_intr_i32(max_intr_i32(I32_(0), y), h));
        (
            ctx.pixels.cast::<T>(),
            v::add(&v::mul(&ay, &[ctx.stride as u32; 16]), &ax),
        )
    }
    // Source: src/opts/SkRasterPipeline_opts.h:6339-6343
    /// Safety: ptr spans size_of::<V>() readable bytes encoding a valid V. No
    /// alignment is required; V must not acquire an owning/destructor obligation.
    pub unsafe fn load<V: Copy, T>(ptr: *const T) -> V {
        let mut value = core::mem::MaybeUninit::<V>::uninit();
        core::ptr::copy_nonoverlapping(
            ptr.cast::<u8>(),
            value.as_mut_ptr().cast::<u8>(),
            core::mem::size_of::<V>(),
        );
        value.assume_init()
    }
    // Source: src/opts/SkRasterPipeline_opts.h:6345-6347
    /// Safety: ptr spans size_of::<V>() exclusively writable live bytes. No
    /// alignment is required; caller preserves typed destination validity.
    pub unsafe fn store<V: Copy, T>(ptr: *mut T, value: V) {
        core::ptr::copy_nonoverlapping(
            (&value as *const V).cast::<u8>(),
            ptr.cast::<u8>(),
            core::mem::size_of::<V>(),
        );
    }
    // Source: src/opts/SkRasterPipeline_opts.h:6404-6410
    /// Safety: ptr is aligned and every indexed T is readable, live and valid.
    /// Every element conversion must be admitted by the original C++ braced
    /// vector initializer and satisfy its defined domain
    /// (float-to-integer finite and destination-representable).
    pub unsafe fn gather<D: Copy, T: Copy + v::CastLane<D>>(ptr: *const T, ix: U32) -> [D; 16] {
        T::gather(ptr, ix, false)
    }
    // Source: src/opts/SkRasterPipeline_opts.h:6412-6415
    /// Safety: every indexed T-sized byte span is live/readable and encodes a valid
    /// T; unlike gather no typed pointer alignment is required. Every conversion
    /// must be admitted by the native braced initializer and satisfy the original
    /// C++ defined domain, including float-to-int bounds.
    pub unsafe fn gather_unaligned<D: Copy, T: Copy + v::CastLane<D>>(
        ptr: *const T,
        ix: U32,
    ) -> [D; 16] {
        gather(ptr, ix)
    }
}

