pub mod lsx_pipe_transcendental {
    use super::lsx_pipe_highp_vectors as v;

    use super::lsx_pipe::{self as n, F, F_, U32_};

    // Source: src/opts/SkRasterPipeline_opts.h:1608-1608
    pub fn fract(x: F) -> F {
        v::sub(&x, &n::floor_(x))
    }
    // Source: src/opts/SkRasterPipeline_opts.h:1611-1619
    pub fn approx_log2(x: F) -> F {
        let bits = x.map(f32::to_bits);
        let e = v::mul(&n::cast(bits), &F_(1.0 / (1 << 23) as f32));
        let m =
            v::bit_or(&v::bit_and(&bits, &U32_(0x007fffff)), &U32_(0x3f000000)).map(f32::from_bits);
        v::sub(
            &n::nmad(m, F_(1.498030302), v::sub(&e, &F_(124.225514990))),
            &v::div(&F_(1.725879990), &v::add(&F_(0.3520887068), &m)),
        )
    }
    // Source: src/opts/SkRasterPipeline_opts.h:1621-1624
    pub fn approx_log(x: F) -> F {
        v::mul(&F_(0.69314718), &approx_log2(x))
    }
    // Source: src/opts/SkRasterPipeline_opts.h:1626-1636
    pub fn approx_pow2(x: F) -> F {
        let f = fract(x);
        let mut approx = n::nmad(f, F_(1.490129070), v::add(&x, &F_(121.274057500)));
        approx = v::add(
            &approx,
            &v::div(&F_(27.728023300), &v::sub(&F_(4.84252568), &f)),
        );
        approx = v::mul(&approx, &F_((1 << 23) as f32));
        approx = n::min_f32(n::max_f32(approx, F_(0.0)), F_(0x7f800000u32 as f32));
        n::round(approx).map(f32::from_bits)
    }
    // Source: src/opts/SkRasterPipeline_opts.h:1638-1641
    pub fn approx_exp(x: F) -> F {
        approx_pow2(v::mul(&F_(1.4426950408889634074), &x))
    }
    // Source: src/opts/SkRasterPipeline_opts.h:1643-1646
    pub fn approx_powf(x: F, y: F) -> F {
        n::if_then_else_f32(
            v::bit_or(&v::cmp_eq(&x, &F_(0.0)), &v::cmp_eq(&x, &F_(1.0))),
            x,
            approx_pow2(v::mul(&approx_log2(x), &y)),
        )
    }
    // Source: src/opts/SkRasterPipeline_opts.h:1648-1648
    pub fn approx_powf_scalar(x: F, y: f32) -> F {
        approx_powf(x, F_(y))
    }
}
