    // F is the actual CPU-domain SIMD/scalar type, never a State pointer.
    // Field order is native; repr(C) is not a claim of tested ABI compatibility.
    #[repr(C)]
    pub struct Params<F> {
        pub dx: usize,
        pub dy: usize,
        pub base: *mut u8,
        pub dr: F,
        pub dg: F,
        pub db: F,
        pub da: F,
    }

