    // The native destination's uninitialized upper bytes remain uninitialized.
    // This is not a zero-extension or an initialized vector with invented lanes.
    pub unsafe fn widen_cast<D: Copy, S: Copy>(src: &S) -> MaybeUninit<D> {
        assert!(size_of::<D>() > size_of::<S>());
        let mut dst = MaybeUninit::<D>::uninit();
        unsafe {
            core::ptr::copy_nonoverlapping(
                (src as *const S).cast::<u8>(),
                dst.as_mut_ptr().cast::<u8>(),
                size_of::<S>(),
            );
        }
        dst
    }
    // Rust same-bit-layout value copy at explicit helper/register boundaries.
    // Safety: both sizes match and copied bytes are valid in the target type.
    pub unsafe fn bit_copy<D: Copy, S: Copy>(src: S) -> D {
        assert!(size_of::<D>() == size_of::<S>());
        let mut dst = MaybeUninit::<D>::uninit();
        unsafe {
            core::ptr::copy_nonoverlapping(
                (&src as *const S).cast::<u8>(),
                dst.as_mut_ptr().cast::<u8>(),
                size_of::<S>(),
            );
            dst.assume_init()
        }
    }
