pub mod native_widen_prefix {
    use super::native_stage_values::{I16x4, U16x4, U16x8, U32x8, U8x4};
    use core::{
        intrinsics::simd,
        mem::{size_of, MaybeUninit},
    };

    /// Safety: the first size_of::<P>() bytes of full are initialized and encode
    /// a valid P. Remaining bytes need not be initialized and are never read.
    /// All callers below use precisely the eight bytes copied from native U16.
    #[inline(always)]
    unsafe fn initialized_prefix<P: Copy, D: Copy>(full: &MaybeUninit<D>) -> P {
        assert!(size_of::<P>() <= size_of::<D>());
        unsafe { core::ptr::read_unaligned(full.as_ptr().cast::<P>()) }
    }
    /// Safety: both operands have initialized four-u16 prefixes. Native widen
    /// upper halves remain uninitialized. Shuffle indexes select only these
    /// four lanes of each operand, yielding eight fully initialized lanes.
    #[inline(always)]
    pub unsafe fn unpacklo_u16<D: Copy>(left: &MaybeUninit<D>, right: &MaybeUninit<D>) -> U16x8 {
        let left: U16x4 = unsafe { initialized_prefix(left) };
        let right: U16x4 = unsafe { initialized_prefix(right) };
        unsafe {
            simd::simd_shuffle(
                left,
                right,
                const { U32x8::from_array([0, 4, 1, 5, 2, 6, 3, 7]) },
            )
        }
    }
    /// Safety: input contains the initialized four-u16 prefix of native U16.
    /// _mm_packus_epi16 interprets these bits as signed i16. Only the first
    /// four packed bytes survive the native sk_unaligned_load<U8>; SIMD
    /// comparisons/selects/cast compute that prefix without reading upper lanes.
    #[inline(always)]
    pub unsafe fn packus_epi16_low<D: Copy>(input: &MaybeUninit<D>) -> U8x4 {
        let input: I16x4 = unsafe { initialized_prefix(input) };
        let zero = I16x4::splat(0);
        let max = I16x4::splat(255);
        let below: I16x4 = unsafe { simd::simd_lt(input, zero) };
        let nonnegative = unsafe { simd::simd_select(below, zero, input) };
        let above: I16x4 = unsafe { simd::simd_gt(nonnegative, max) };
        let saturated = unsafe { simd::simd_select(above, max, nonnegative) };
        unsafe { simd::simd_cast(saturated) }
    }
    /// Safety: input contains the initialized four-u16 prefix. LSX vsat_hu is
    /// unsigned saturation; vpickev_b keeps the low byte of each saturated
    /// halfword, and native U8 reads just the first four resulting bytes.
    #[inline(always)]
    pub unsafe fn vsat_hu_pickev_b_low<D: Copy>(input: &MaybeUninit<D>) -> U8x4 {
        let input: U16x4 = unsafe { initialized_prefix(input) };
        let max = U16x4::splat(255);
        let above: I16x4 = unsafe { simd::simd_gt(input, max) };
        let saturated = unsafe { simd::simd_select(above, max, input) };
        unsafe { simd::simd_cast(saturated) }
    }
}
